"""A Level English Language (0730), Lower Sixth: Grammar (19 lessons, one practice set each in the practice file).

Builds on the O Level grammar lessons (f5_eng_02_grammar.py) and does not repeat them: here we go to A Level depth.
All example sentences are original and invented; names, places and figures are invented.
Where British and other usage differ, or textbooks differ, the lesson says 'check your textbook'.
"""

from .dsl import *  # noqa: F403

COURSE = ("english-language", "lower-sixth")

M = "Grammar"
T_POS = "Parts of speech"
T_NOUN = "Nouns and quantifiers"
T_VERB = "Verbs: tense, mood, modals and voice"
T_REP = "Reported speech"
T_VERBAL = "Gerunds, infinitives and participles"
T_PRON = "Pronouns and determiners"
T_STYPE = "Sentence types"
T_AGR = "Agreement, fragments, run-on sentences and modifiers"
T_CLAUSE = "Clauses"
T_COMP = "Comparatives, conjunctions and word order"
T_FORMS = "Word forms"
T_PUNCT = "Punctuation"

C1 = ("Cameroon's GCE English Language Paper 1 Section C is 20 multiple-choice grammar questions, one mark each. "
      "Every option looks possible at first glance, so you win marks by knowing the rule, not by 'feeling' what sounds right.")

LESSONS = []

# ================================================================== 1. Parts of speech
LESSONS.append(lesson(
    module=M, topic=T_POS,
    title="Parts of speech: a word's job decides its class",
    slug="enl2-parts-of-speech-function",
    minutes=20,
    summary="A word belongs to a part of speech only in a sentence: the same word can be a noun, verb, adjective, adverb, preposition or conjunction depending on its job there.",
    objectives=["Name the seven main parts of speech and say what each does", "Decide a word's class from its job in the sentence, not from its spelling or ending",
                "Tell prepositions, conjunctions and adverbs apart when one word can be all three", "Recognise nouns used as modifiers and verbs used with particles"],
    key_concepts=["Part of speech (word class)", "Function", "Conversion", "Preposition v conjunction", "Noun adjunct"],
    blocks=[
        H("Introduction"),
        T("At O Level you learnt to name the parts of speech. At A Level the question changes. Paper 1 Section C does not ask 'what is a noun?'. It shows one word in a sentence and asks what class it is, or it uses the same word twice and asks how the jobs differ. So the skill is this: **look at what the word does in this sentence.**"),
        T("Take the word *round*. In 'a round table' it is an adjective, but in 'the first round of the match' it is a noun. A word has a class only inside a sentence."),
        H("The seven main parts of speech"),
        D("A **part of speech** (or **word class**) is a group of words that do the same job in a sentence. The Board's syllabus lists seven: noun, verb, adjective, pronoun, adverb, preposition and conjunction. (Determiners, such as *the* and *some*, have their own lesson later.)", title="Definition"),
        KEY("What each class does", "Ask one question of each word: what is its job here?", cards=[
            ["Noun", "Names a person, place, thing, idea or quality: *Douala, honesty, tomatoes*."],
            ["Verb", "Shows an action, event or state: *run, happen, seem*."],
            ["Adjective", "Describes or limits a noun or pronoun: *a heavy bag, she is tired*."],
            ["Pronoun", "Stands in place of a noun: *they, mine, who*."],
            ["Adverb", "Describes a verb, adjective, another adverb or a whole sentence: *spoke quietly, very kind, Fortunately, we won*."],
            ["Preposition", "Links a noun or pronoun to the rest of the sentence, showing place, time or relation: *in the market, after school*."],
            ["Conjunction", "Joins words, phrases or clauses: *and, but, because, although*."]]),
        H("Same word, different class"),
        T("English makes new uses of old words without changing their spelling. This is called **conversion**. The test is always the job."),
        EX("Worked example 1: the word *round*", intro="Name the class of *round* in each sentence.", steps=[
            S("She bought a round table.", text="*Round* describes the noun *table*. It is an **adjective**."),
            S("The children ran round.", text="*Round* describes how they ran and has no noun after it. It is an **adverb**."),
            S("The ball rolled round the corner.", text="*Round* links *the corner* to *rolled*. It is a **preposition** (British usage; see the note below)."),
            S("He lost in the first round.", text="*Round* is the thing named, with *the first* before it. It is a **noun**."),
            S("They round the price up to 500 FCFA.", text="*Round* is what they do. It is a **verb**."),
        ]),
        T("Note: many British dictionaries list *round the corner* with *round* as a preposition, and American usage often prefers *around*. Both are correct English. Check your textbook for which word it uses in this kind of answer."),
        EX("Worked example 2: prepositions, conjunctions and adverbs", intro="The word *after* appears three times. Classify it each time.", steps=[
            S("We left after lunch.", text="*Lunch* is a noun phrase, not a clause. *After* is a **preposition**."),
            S("We left after we had eaten.", text="*We had eaten* is a clause (subject plus verb). *After* joins two clauses: a **conjunction**."),
            S("We left soon after.", text="Nothing follows *after*, and it says when. It is an **adverb**."),
        ], check=r"\text{preposition} + \text{noun phrase};\ \text{conjunction} + \text{clause};\ \text{adverb alone}"),
        TIP("The quickest test for *before, after, since, until, as, for, but*: if a clause (with its own verb) follows, the word is a conjunction. If only a noun or pronoun follows, it is a preposition. If nothing follows, it is probably an adverb."),
        H("Two more traps"),
        T("**Nouns that behave like adjectives.** In *a school bus*, *a palm oil lamp* and *the market women*, the first word names a thing, but it is placed before another noun to describe it. Many grammar books call such a word a **noun adjunct** (a noun used as a modifier). Some books simply call it an adjective. Check your textbook for the term it uses; the better exam answer is the one that says what the word does."),
        T("**Verbs with particles.** In *look up the word* and *switch off the generator*, the little word is part of the verb phrase. Textbooks differ: some say these words are adverbs, others say 'particles'. Phrasal verbs are covered again in the O Level lessons; here, remember that such a word is not a preposition when it can move after the object: *switch the generator off*."),
        MISTAKE("Judging by the ending", "A word ending in *-ly* is not always an adverb. *Friendly, lovely, elderly, early* can be adjectives: *a friendly teacher*. And *fast, hard, late* can be adjectives or adverbs without any *-ly*. *Hardly* is a different word from *hard*. Always look at the job."),
        MISTAKE("Thinking 'that' has one class", "*That* is a determiner in *that bus*, a pronoun in *I like that*, and a conjunction in *I know that he is late*. The same applies to *what, which, since* and *but*."),
        QUIZ("In 'She has lived in Buea since 2019', the word *since* is a", ["conjunction", "preposition", "adverb", "adjective"], 1,
             "*Since* is followed by *2019*, a noun phrase with no verb of its own. So it is a preposition.",
             hint="Is a clause (subject plus verb) or just a noun phrase after it?",
             feedback=["A conjunction would be followed by a clause, such as *since she arrived*.", "", "An adverb would stand alone, as in *She has lived here ever since*.", "It does not describe a noun."]),
        QUIZ("In which sentence is *light* a noun?", ["Carry a light bag.", "The light went out.", "Please light the lamp.", "The room is very light."], 1,
             "*The light* names a thing and follows *the*. In the others it describes (adjective), is an action (verb) or describes the room (adjective).",
             hint="Which sentence has an article before *light* and no other word being described?",
             feedback=["*Light* describes *bag*: adjective.", "", "*Light* is an action: verb.", "*Light* describes the room: adjective."]),
        PQ("Name the class of the word in capitals. (a) The students waited UNTIL the rain stopped. (b) The students waited UNTIL noon. (c) She sings VERY well.",
           "(a) **Conjunction**: a clause (*the rain stopped*) follows. (b) **Preposition**: only a noun (*noon*) follows. (c) **Adverb**: *very* describes another adverb, *well*."),
        PQ("Use *hard* as (a) an adjective and (b) an adverb in two sentences of your own.",
           "Model: (a) *It was a hard question.* *Hard* describes *question*. (b) *She worked hard all term.* *Hard* describes how she worked."),
        PQ("In 'The market women sell fruit', what class is *market*? Give your answer in two ways, because textbooks differ.",
           "It is a noun by form, used as a modifier of *women*: a **noun adjunct** (some textbooks call it an adjective). Check your textbook for the term to use."),
        SUM("A word belongs to a part of speech only in a sentence: ask what it does there.",
            "Seven main classes: noun, verb, adjective, pronoun, adverb, preposition, conjunction.",
            "Conversion lets one spelling serve several classes (*round, light, hard, fast*).",
            "Preposition plus noun phrase; conjunction plus clause; adverb alone.",
            "*-ly* does not prove that a word is an adverb."),
    ],
))

# ================================================================== 2. Nouns and quantifiers
LESSONS.append(lesson(
    module=M, topic=T_NOUN,
    title="Count and non-count nouns, and the quantifiers that go with them",
    slug="enl2-count-noncount-quantifiers",
    minutes=22,
    summary="Count nouns can be counted and have plurals; non-count nouns (information, advice, luggage) cannot, and each type takes its own quantifiers: many/few/fewer with count, much/little/less with non-count.",
    objectives=["Sort nouns into count, non-count and plural-only types", "Avoid false plurals such as 'informations', 'furnitures' and 'a news'",
                "Choose the correct quantifier: much/many, little/a little, few/a few, less/fewer, amount/number", "Spot nouns whose meaning changes between count and non-count use"],
    key_concepts=["Count noun", "Non-count (mass) noun", "Quantifier", "Plural-only noun", "A piece of"],
    blocks=[
        H("Introduction"),
        T("Candidates in every GCE session write sentences like 'The teacher gave us many informations' or 'I bought two furnitures'. Both are wrong, and the same mistake costs marks in Paper 1 Section C and in the accuracy mark of composition. Underneath is one idea: **some English nouns cannot be counted**, and the words we put in front of them (the quantifiers) must match."),
        H("Count and non-count nouns"),
        D("A **count noun** names things we can count one by one. It has a singular and a plural form: *a book, two books*. A **non-count noun** (also called a mass or uncountable noun) names something we see as a mass, a substance or an idea. It has no plural and takes no *a/an*: *information, rice, advice*.", title="Definition"),
        CODE("Count (singular + plural)      Non-count (one form only)\nchair, chairs                  furniture\nbag, bags                      luggage (baggage)\nsuggestion, suggestions        advice\nfact, facts                    information\ntool, tools                    equipment\njob, jobs                      work\nlesson, lessons                homework\nroad, roads                    traffic\nstory, stories                 news\nresult, results                evidence, progress, research", "text", title="Common pairs: the same idea, count v non-count"),
        T("Non-count nouns take a singular verb: *The news is good. The equipment was expensive.* To count them, use a unit word: **a piece of information, two pieces of advice, an item of furniture, a bag of rice, a bottle of water**."),
        T("**Plural-only nouns** have a plural form and no singular: *scissors, trousers, glasses (spectacles), clothes, goods, belongings, thanks, congratulations*. For a single item, use *a pair of*: *a pair of scissors*. Subjects such as *mathematics, physics* and *news* look plural but are singular."),
        T("**Some nouns are count in one meaning and non-count in another.** *Paper* is a material (non-count: *a sheet of paper*) but *a paper* is a newspaper or an exam paper. *Experience* is non-count when it means skill gained over time (*She has a lot of experience*) and count when it means an event (*It was a strange experience*). *Hair, time, work, glass* behave in the same way. Check a good dictionary: it marks each meaning [C] or [U]."),
        H("Quantifiers"),
        D("A **quantifier** is a word or phrase that tells us how much or how many: *some, any, many, much, few, little, a lot of, several*.", title="Definition"),
        CODE("With COUNT nouns only      With NON-COUNT nouns only    With both\nmany   (many books)       much   (much water)          some, any, a lot of,\n(a) few (a few books)       (a) little (a little rice)   lots of, plenty of, no,\nfewer  (fewer books)        less   (less rice)           more, most, all\nseveral, a number of        a great deal of, an amount of", "text", title="Which quantifier with which noun"),
        KEY("Few or a few? Little or a little?", "The small word *a* changes the meaning.", cards=[
            ["a few / a little", "A positive idea: there is some, and it is enough or useful. *We have a little time, so let us begin.*"],
            ["few / little", "A negative idea: there is hardly any. *Few students passed; little help was available.*"]]),
        T("**Much and many** are mostly used in negative sentences and questions: *We do not have much time. How many are there?* In plain positive statements, a lot of / plenty of is more natural: *We have a lot of time.* (*Much time* in a positive sentence sounds formal or old-fashioned, but *too much, so much, as much* are fine.)"),
        T("**Less and fewer.** Traditional grammar books say *fewer* goes with count nouns (*fewer mistakes*) and *less* with non-count nouns (*less noise*). In everyday speech many people say 'less than ten items'. For exams, follow the traditional rule: check your textbook. Likewise **amount** goes with non-count nouns (*the amount of rain*) and **number** with count nouns (*the number of students*)."),
        EX("Worked example 1: correcting false plurals", intro="Correct the error: 'The head teacher gave the prefects many advices and some informations about the new rules.'", steps=[
            S("Find the non-count nouns", text="*Advice* and *information* are non-count. They have no plural."),
            S("Replace *many* with a quantifier that fits", text="*Many* needs a count noun. Use *a lot of* or *some*."),
            S("Rewrite", text="'The head teacher gave the prefects a lot of advice and some information about the new rules.'"),
        ], check=r"\text{advice, information: no } -s;\ \text{many} \to \text{a lot of / some}"),
        EX("Worked example 2: few, a few, little, a little", intro="Choose the correct word: (a) 'There is (little / a little) rice left, so we can cook for two people.' (b) 'There is (little / a little) water in the tank; the family must be careful.'", steps=[
            S("Decide whether the meaning is positive or negative", text="(a) 'so we can cook' shows that there is enough: positive. (b) 'must be careful' shows that there is hardly enough: negative."),
            S("Choose", text="(a) **a little**. (b) **little**."),
        ]),
        EX("Worked example 3: amount or number, less or fewer", intro="Complete: 'The (amount / number) of students who arrived late fell this term, so the principal saw (less / fewer) late-comers.'", steps=[
            S("Students can be counted", text="So *number* and *fewer* (traditional rule)."),
            S("Complete", text="'The **number** of students ... **fewer** late-comers.'"),
        ]),
        MISTAKE("Adding -s to non-count nouns", "*Informations, advices, furnitures, equipments, luggages, researches, evidences, homeworks* are all errors in standard exam English. Use the unit phrase to count them: *two pieces of advice*. (*Researches* and *works* occasionally appear in formal writing for special meanings, but do not use them in an exam unless you are sure.)"),
        MISTAKE("A news, a progress, an advice", "Non-count nouns cannot take *a/an*. Write *a piece of news*, *some progress*, *a piece of advice*. Likewise *The news are good* is wrong: *The news is good.*"),
        QUIZ("Which sentence is correct?", ["Many informations were given to the visitors.", "A lot of information was given to the visitors.", "A lot of informations were given to the visitors.", "Many information was given to the visitors."], 1,
             "*Information* is non-count: no -s, singular verb, and a quantifier like *a lot of* or *much*.", hint="Can you say 'one information, two informations'?",
             feedback=["*Informations* is not standard English.", "", "Same error: no plural for *information*.", "*Many* is used with plural count nouns."]),
        QUIZ("'The council has built ______ new classrooms this year.' Choose the best word.", ["much", "a little", "several", "an amount of"], 2,
             "*Classrooms* is a plural count noun, so *several* fits. The others are used with non-count nouns.", hint="Is *classrooms* a count or a non-count noun?",
             feedback=["*Much* goes with non-count nouns.", "*A little* goes with non-count nouns.", "", "*Amount of* goes with non-count nouns."]),
        PQ("Rewrite correctly: 'She packed two luggages and a furniture for her new room.'",
           "'She packed two **bags** (or *two pieces of luggage*) and **an item of furniture** (or *some furniture*) for her new room.' *Luggage* and *furniture* are non-count: no plural and no *a/an*."),
        PQ("Explain the difference in meaning between 'He has few friends in town' and 'He has a few friends in town'.",
           "*Few* means hardly any: he is rather lonely (negative). *A few* means some: he has enough friends (positive)."),
        PQ("Fill in with *much* or *many* and say why. (a) How ______ money did you spend? (b) How ______ tickets did you buy?",
           "(a) **much**: *money* is non-count. (b) **many**: *tickets* is a plural count noun."),
        SUM("Count nouns have plurals and can take a/an; non-count nouns have one form and no a/an.",
            "Information, advice, furniture, luggage, equipment, news, progress and evidence are non-count.",
            "Use a unit phrase to count non-count nouns: a piece of advice.",
            "Many, few, fewer, number go with count nouns; much, little, less, amount with non-count nouns.",
            "A few and a little are positive; few and little are negative."),
    ],
))

# ================================================================== 3. Tense, aspect and state verbs
LESSONS.append(lesson(
    module=M, topic=T_VERB,
    title="Tense and aspect: choosing the verb form that fits the time",
    slug="enl2-tense-aspect-state-verbs",
    minutes=22,
    summary="Tense places an action in time, aspect shows how it is viewed (finished, in progress, linked to now); time markers, sequence of events and state verbs decide which verb form is correct.",
    objectives=["Separate tense (time) from aspect (completed or in progress)", "Choose between past simple, present perfect and past perfect using time markers and sequence",
                "Use present forms for future time in time and condition clauses", "Recognise state verbs that are not normally used in the continuous"],
    key_concepts=["Tense", "Aspect", "Present perfect", "Past perfect", "State verb", "Time marker"],
    blocks=[
        H("Introduction"),
        T("You already know the twelve tense names from O Level. A Level questions use that knowledge to test **choice**: 'which form fits this sentence?'. The sentence usually contains a clue (a word such as *yesterday*, *since* or *by the time*), and the correct form is the one that agrees with the clue. This lesson teaches you to read those clues."),
        H("Tense and aspect"),
        D("**Tense** shows when something happens in relation to now: present or past (English has no true future tense form of the verb; we show the future with *will*, *going to* and other forms). **Aspect** shows how the speaker views the action: **simple** (a fact or complete event), **continuous** (in progress) or **perfect** (completed, with a link to a later time).", title="Definition"),
        CODE("               Simple        Continuous          Perfect             Perfect continuous\nPresent        she writes    she is writing      she has written     she has been writing\nPast           she wrote     she was writing     she had written     she had been writing", "text", title="Present and past, four aspects"),
        H("Past simple, present perfect and past perfect"),
        KEY("Which one?", "Match the form to the time clue.", cards=[
            ["Past simple", "A finished time that is named or understood: yesterday, last year, in 2019, ten minutes ago, when I was young. *The bus left at six.*"],
            ["Present perfect", "A past action linked to now, with no finished time named: already, just, yet, ever, never, since, for, so far, this week. *The bus has left.* (and it is not here now)"],
            ["Past perfect", "An action completed before another past action or time. *When we reached the station, the bus had left.*"]]),
        T("Why is 'I have seen her yesterday' wrong? Because *yesterday* names a finished time, so the past simple is needed: *I saw her yesterday.* And 'She is living in Garoua since 2020' is wrong because *since* needs a perfect form: *She has lived* (or *has been living*) *in Garoua since 2020.*"),
        T("**For and since.** *For* is followed by a length of time (*for three years*); *since* by a starting point (*since 2021, since Monday*). Both usually take the present perfect when the situation continues up to now."),
        EX("Worked example 1: choosing the form", intro="Choose the correct form. (a) 'We (have met / met) the new principal last Friday.' (b) 'By the time the rain started, the farmers (harvested / had harvested) the maize.'", steps=[
            S("Read the clue in (a)", text="*Last Friday* is a finished time, so the past simple: **met**."),
            S("Read the clue in (b)", text="Two past events: harvesting happened first, rain second. The earlier one takes the past perfect: **had harvested**."),
        ]),
        H("Future time in time and condition clauses"),
        T("After *when, as soon as, before, after, until, if, unless*, we use a **present** form even when we mean the future: 'I will call you when she **arrives**' (not 'will arrive'). 'If it **rains**, the match will be cancelled' (not 'will rain')."),
        T("The future can also be shown by *going to* (a plan or visible evidence), the present continuous (a fixed arrangement: *We are meeting at nine*) and the present simple (a timetable: *The train leaves at 7.15*). Many textbooks say *shall* goes with *I/we* in British English, while *will* is now common with every person: check your textbook."),
        EX("Worked example 2: time clauses", intro="Correct the error: 'When the results will be published, the students will check them online.'", steps=[
            S("Find the time word", text="*When* begins a time clause."),
            S("Change the verb in that clause to a present form", text="'will be published' becomes *are published*."),
            S("Result", text="'When the results **are published**, the students will check them online.'"),
        ]),
        H("State verbs"),
        D("**State verbs** describe conditions, thoughts and feelings, not actions in progress: *know, believe, understand, want, need, like, love, hate, belong, own, seem, contain, mean*. They are normally used in simple forms: 'I **know** the answer', not 'I am knowing the answer'.", title="Definition"),
        T("Some verbs have a state meaning and an action meaning. *She has a car* (state: possesses) but *She is having lunch* (action). *I think it is late* (opinion) but *I am thinking about the offer* (mental action). *The soup tastes salty* (state) but *The cook is tasting the soup* (action). In informal speech, *I am loving it* is a well-known slogan; in an exam, keep to the standard rule."),
        EX("Worked example 3: continuous or not?", intro="Which sentence is correct? (a) 'She is owning two shops.' (b) 'She owns two shops.'", steps=[
            S("Identify the verb type", text="*Own* is a state verb."),
            S("Decide", text="State verbs are not normally continuous, so **(b)** is correct."),
        ]),
        MISTAKE("Present perfect with a finished time", "Never combine the present perfect with *yesterday, last week, in 2018, ago, when I was a child*. Use the past simple."),
        MISTAKE("Will after if, when and until", "Do not write 'if you will come' or 'until he will return'. Use the present: *if you come, until he returns*. (An exception, 'If you will wait here, I shall call him', is a polite request, not a condition.)"),
        QUIZ("'Ngu ______ in Bamenda since he was ten.'", ["lives", "has lived", "lived", "is living"], 1,
             "*Since he was ten* links the past to now, so the present perfect: *has lived* (or *has been living*).", hint="What does *since* require?",
             feedback=["The simple present does not link a past starting point to now.", "", "The past simple would mean he no longer lives there.", "The present continuous does not go with *since*."]),
        QUIZ("'The students had left before the guest of honour ______.'", ["arrived", "has arrived", "arrives", "was arriving"], 0,
             "The past perfect (*had left*) describes the earlier event, so the later one is in the past simple: *arrived*.", hint="Which event came second?",
             feedback=["", "The present perfect does not go with a past perfect in this way.", "The present tense does not match a past story.", "The continuous suggests the arriving was in progress, not an event."]),
        PQ("Correct the sentence: 'I am knowing the teacher since 2021.'",
           "'I **have known** the teacher since 2021.' *Know* is a state verb (no continuous) and *since* needs a perfect form."),
        PQ("Explain why 'We have visited the museum last Saturday' is wrong, and correct it.",
           "*Last Saturday* is a finished time, so the present perfect cannot be used. Correct: 'We **visited** the museum last Saturday.'"),
        PQ("Join the two events with the past perfect: 'The bell rang. The pupils entered the hall.' (The pupils were already in the hall when the bell rang.)",
           "'The pupils **had entered** the hall when the bell rang.' The earlier event (entering) takes the past perfect."),
        SUM("Tense is time; aspect is how the action is viewed.",
            "Past simple goes with a finished time; present perfect links the past to now; past perfect is the earlier of two past events.",
            "For + length of time; since + starting point.",
            "After when, if, until, after, before: use a present form for future time.",
            "State verbs (know, own, want, believe) are not normally used in the continuous."),
    ],
))

# ================================================================== 4. Modals
LESSONS.append(lesson(
    module=M, topic=T_VERB,
    title="Modal verbs: ability, permission, certainty, obligation and advice",
    slug="enl2-modal-verbs",
    minutes=24,
    summary="Modal verbs (can, may, must, should, might...) add meaning such as ability, permission, certainty, obligation and advice; they take the base verb, never -s or to, and the perfect modals (should have, must have) talk about the past.",
    objectives=["State the form rules of modal verbs and spot errors such as 'cans' and 'must to go'", "Match each modal to its function: ability, permission, possibility, deduction, obligation, advice",
                "Distinguish must, have to, mustn't and needn't", "Use modal + have + past participle for past deduction, criticism and unnecessary action"],
    key_concepts=["Modal verb", "Base form", "Deduction", "Obligation v prohibition", "Perfect modal"],
    blocks=[
        H("Introduction"),
        T("When a teacher says 'You may go', 'You should go' or 'You must go', the action is the same, but the meaning is different: permission, advice, command. The small verbs that carry these shades of meaning are called **modal verbs**. They are a favourite in Paper 1 Section C because several options usually look grammatical and only one fits the meaning."),
        H("Form: three rules that never change"),
        D("The central **modal verbs** are *can, could, may, might, will, would, shall, should, must* (and *ought to*). They are used with another verb to show ability, permission, possibility, obligation and similar ideas.", title="Definition"),
        KEY("Form rules", "Modals are 'defective': they do not behave like ordinary verbs.", cards=[
            ["No -s", "*She can swim.* Not *She cans*."],
            ["Base verb after", "*He must go.* Not *must to go* or *must goes*. (*Ought* is the exception: *ought to go*.)"],
            ["No do-support", "*Can you swim? I cannot swim.* Not *Do you can swim?*"]]),
        T("Because modals have no infinitive, we borrow other words when we need one: *be able to* for *can* (*She will be able to swim*), *have to* for *must* (*We had to wait*)."),
        H("Meanings (functions)"),
        CODE("ABILITY        can, could (general), be able to (one achievement)\nPERMISSION     may (formal), can/could (less formal)\nPOSSIBILITY    may, might, could\nDEDUCTION      must (sure it is true), can't (sure it is not)\nOBLIGATION     must, have to, need to\nPROHIBITION    mustn't, can't, may not\nNO NECESSITY   needn't, don't have to\nADVICE         should, ought to, had better\nOFFER/SUGGEST  shall I...?, shall we...?", "text", title="Modal meanings at a glance"),
        T("**Ability.** *I can type fast* (general ability now). *She could run a kilometre when she was ten* (general past ability). For one particular success in the past, use *was able to*: 'Despite the storm, the pilot **was able to** land safely.' (Many books accept *couldn't* for a single failure: *The pilot couldn't land*. Check your textbook.)"),
        T("**Permission.** *May I use your phone?* is polite and formal. *Can I...?* is common in speech and is accepted in many books, though some teachers prefer *may* in exams: check your textbook."),
        T("**Degrees of certainty** (about the present or future). From most to least certain: *must / can't* (strong deduction) > *should* (expectation) > *may / might / could* (possibility). 'The lights are on, so someone **must** be at home.' 'That **can't** be Ako; he is in Yaounde this week.'"),
        T("**Obligation, prohibition and absence of obligation.** *Must* and *have to* both show obligation: *must* often comes from the speaker (*I must finish this tonight*), *have to* from a rule or outside force (*Students have to wear uniform*). *Mustn't* means 'it is forbidden', but *don't have to* and *needn't* mean 'it is not necessary'. This difference is tested again and again."),
        H("Modals about the past: modal + have + past participle"),
        KEY("Past forms", "The pattern is modal + *have* + past participle.", cards=[
            ["must have + pp", "Past deduction: *The road is wet. It must have rained.*"],
            ["can't / couldn't have + pp", "Sure it did not happen: *She can't have seen me; she was away.*"],
            ["might / may / could have + pp", "Possible past event (or an unrealised chance): *He might have missed the bus.*"],
            ["should have + pp", "Criticism or regret: *You should have called me.*"],
            ["needn't have + pp", "We did it, but it was not necessary: *I needn't have brought an umbrella.*"]]),
        EX("Worked example 1: deduction", intro="'Ndi is not answering his phone and his shop is closed.' Complete: 'He (must / can't) be away.' Then change to the past: 'Nobody saw him yesterday. He (must / can't) have left early.'", steps=[
            S("Decide the strength of the evidence", text="Both clues point strongly to 'away': *must* (sure it is true)."),
            S("Past form", text="*Must have left* is sure deduction about the past."),
            S("Answer", text="'He **must** be away.' 'He **must have left** early.'"),
        ]),
        EX("Worked example 2: must, mustn't, needn't", intro="Choose the correct modal. (a) 'You ______ run in the corridors; it is dangerous.' (b) 'You ______ bring a pen; the school will give you one.'", steps=[
            S("(a) forbidden", text="Dangerous, so not allowed: **mustn't**."),
            S("(b) not necessary", text="The school provides one, so there is no need: **needn't** (or *don't have to*)."),
        ], check=r"\text{mustn't} = \text{forbidden};\ \text{needn't} = \text{not necessary}"),
        EX("Worked example 3: should have", intro="Ayuk did not revise and failed a test. Write a sentence of criticism.", steps=[
            S("Use should + have + past participle", text="'Ayuk **should have revised**.'"),
            S("Check the meaning", text="It means he did not revise (the revising did not happen), and we think it was wrong."),
        ]),
        MISTAKE("Adding -s, to or do", "Wrong: *She cans speak French*, *You must to leave*, *Do you can drive?*, *He should goes*. Right: *She can speak French*, *You must leave*, *Can you drive?*, *He should go*. Also avoid 'can able to' and 'could can'."),
        MISTAKE("Mixing mustn't and don't have to", "*You mustn't come* means you are forbidden to come. *You don't have to come* means coming is optional. They are opposites in feeling even though they look alike."),
        QUIZ("'The road is flooded, so the bus ______ be late.'", ["mustn't", "might", "needn't", "daren't"], 1,
             "A possibility about the future: *might*. *Mustn't* forbids, *needn't* means not necessary.", hint="Is the sentence forbidding, advising or guessing?",
             feedback=["*Mustn't* means it is forbidden.", "", "*Needn't* means it is not necessary.", "*Daren't* means 'does not dare', which is not the meaning."]),
        QUIZ("'I wore a coat, but it was warm. I ______ it.'", ["needn't have worn", "mustn't have worn", "can't wear", "shouldn't wear"], 0,
             "*Needn't have + past participle* says the action happened but was not necessary.", hint="Did the action happen? Was it needed?",
             feedback=["", "*Mustn't have* is not used for this meaning.", "*Can't wear* is about the present.", "*Shouldn't wear* is advice about the present."]),
        PQ("Correct the errors: (a) 'She cans cook very well.' (b) 'You must to submit the form by Friday.'",
           "(a) 'She **can** cook very well.' (b) 'You **must submit** the form by Friday.' Modals take no -s and no *to*."),
        PQ("Explain the difference between 'You mustn't use calculators' and 'You needn't use calculators'.",
           "*Mustn't* means calculators are forbidden. *Needn't* means you may use them but it is not necessary."),
        PQ("Rewrite with a modal perfect: 'I am sure the thief entered through the window.'",
           "'The thief **must have entered** through the window.' *Must have + past participle* gives a strong deduction about the past."),
        SUM("Modals take the base verb: no -s, no to, no do.",
            "Know the functions: ability, permission, possibility, deduction, obligation, advice.",
            "Must/have to = obligation; mustn't = forbidden; needn't/don't have to = not necessary.",
            "Modal + have + past participle talks about the past: must have, can't have, should have, needn't have.",
            "Where books disagree (can v may, couldn't v wasn't able to), check your textbook."),
    ],
))

# ================================================================== 5. Mood and voice
LESSONS.append(lesson(
    module=M, topic=T_VERB,
    title="Mood and voice: the subjunctive, and active and passive forms",
    slug="enl2-mood-and-voice",
    minutes=22,
    summary="Mood shows the speaker's attitude (fact, command, wish or demand); voice shows whether the subject does the action (active) or receives it (passive). Learn the subjunctive forms and the passive in every tense and with modals.",
    objectives=["Name the three moods: indicative, imperative and subjunctive", "Use the subjunctive after verbs of demand and in 'if I were' and 'I wish' clauses",
                "Form the passive in any tense, with modals and with two objects", "Recognise verbs that cannot be passive and decide when the passive is the better choice"],
    key_concepts=["Mood", "Indicative", "Imperative", "Subjunctive", "Passive voice", "Agent"],
    blocks=[
        H("Introduction"),
        T("At O Level, you met the conditional and the passive. Here we add the missing pieces that appear in Section C: **mood**, especially the subjunctive, and the passive in the harder cases (continuous tenses, modals, verbs with two objects)."),
        H("Mood"),
        D("**Mood** is the form of the verb that shows the speaker's attitude to what is said. English has three moods: the **indicative** (statements and questions of fact), the **imperative** (commands and requests) and the **subjunctive** (things that are wished, demanded or imagined, not facts).", title="Definition"),
        CODE("Indicative   The principal speaks to the students every Monday.\nImperative   Open your books. / Please be quiet.\nSubjunctive  The principal insists that every student be on time.\n             If I were the principal, I would build a library.", "text", title="Three moods"),
        T("**The subjunctive in English is small but exam-sized.** Two forms matter."),
        KEY("Two subjunctives", "Learn the pattern, then the exceptions.", cards=[
            ["Present subjunctive: the base verb", "Used in *that*-clauses after verbs and adjectives of demand, advice or importance: *demand, insist, suggest, recommend, propose, request, ask*; *essential, vital, important*. The verb is the plain base form for every person: *The doctor recommends that she **rest**. It is vital that he **be** present.* British English often prefers *should* (*that she should rest*) or the indicative: check your textbook."],
            ["Past subjunctive: were", "Used for unreal conditions and wishes: *If I **were** you, I would apologise. I wish she **were** here.* In informal speech *was* is common (*If I was you*), but exams prefer *were* for all persons: check your textbook."]]),
        T("Fixed phrases keep old subjunctives: *Long live the king*, *Be that as it may*, *so be it*, *come what may*."),
        EX("Worked example 1: choosing the subjunctive", intro="Choose the correct form. (a) 'The coach insists that every player (arrives / arrive) on time.' (b) 'I wish the road (is / were) shorter.'", steps=[
            S("(a) insists that", text="After *insist that* (demand), the base form is used for every person: **arrive** (not *arrives*)."),
            S("(b) wish", text="A wish about something unreal uses the past subjunctive: **were**."),
        ]),
        H("Voice"),
        D("**Voice** shows the relation between the subject and the action. In the **active voice** the subject does the action: *The council repaired the bridge.* In the **passive voice** the subject receives the action: *The bridge was repaired (by the council).* The doer is called the **agent**.", title="Definition"),
        F(r"\text{passive} = \text{subject} + \text{be (in the tense of the active verb)} + \text{past participle}", title="Forming the passive"),
        CODE("TENSE / FORM           ACTIVE                         PASSIVE\nPresent simple        They repair the road.          The road is repaired.\nPresent continuous    They are repairing the road.   The road is being repaired.\nPast simple           They repaired the road.        The road was repaired.\nPast continuous       They were repairing the road.  The road was being repaired.\nPresent perfect       They have repaired the road.   The road has been repaired.\nPast perfect          They had repaired the road.    The road had been repaired.\nFuture (will)         They will repair the road.     The road will be repaired.\nModal                 They must repair the road.     The road must be repaired.\nModal perfect         They should have repaired it.  It should have been repaired.", "text", title="Active to passive in every form"),
        T("Notice that the tense of the verb *be* copies the tense of the active verb, and the main verb always becomes the past participle."),
        EX("Worked example 2: changing voice", intro="Change to the passive: (a) 'The committee will announce the results on Monday.' (b) 'Someone has stolen my bicycle.' (c) 'The council should have built the road.'", steps=[
            S("(a) will announce", text="The object *the results* becomes the subject: 'The results **will be announced** on Monday (by the committee).'"),
            S("(b) has stolen", text="The doer is unknown, so leave out the agent: 'My bicycle **has been stolen**.'"),
            S("(c) should have built", text="Modal perfect passive: 'The road **should have been built** (by the council).'"),
        ]),
        T("**Two objects.** Some verbs (*give, send, show, offer, tell*) have an indirect object (who receives) and a direct object (what is given). 'The school gave Nana a scholarship' has two passives: 'Nana **was given** a scholarship' (the more common) and 'A scholarship **was given** to Nana'."),
        T("**When is the passive the better choice?** Use it when the doer is unknown or unimportant (*The window was broken*), when the receiver is the topic (*The new library was opened by the Governor*), or in a formal report where the action matters more than the actor. Overusing it makes writing heavy."),
        T("**Reporting passives:** 'People say that the pilot is very experienced' can become 'It **is said** that the pilot is very experienced' or 'The pilot **is said** to be very experienced.'"),
        MISTAKE("Passive with intransitive verbs", "Only verbs that take an object can become passive. *Happen, arrive, die, occur, seem, fall* cannot: write *The accident happened*, not *The accident was happened*. Also avoid the passive with state verbs like *have, lack, resemble, suit* in their normal meanings: *She has a car*, not *A car is had by her*."),
        MISTAKE("Leaving out been, or using the wrong participle", "A passive needs a form of *be* plus a past participle. Wrong: *The match was cancel* (wrong participle) and *The match has cancelled by the referee* (no *been*). Right: *The match was cancelled* and *The match has been cancelled by the referee*."),
        QUIZ("'The manager demanded that the report ______ on his desk by noon.'", ["is", "was", "be", "will be"], 2,
             "After *demanded that*, the present subjunctive uses the base form for every person: *be*.", hint="Which verb of demand is in the sentence?",
             feedback=["The indicative does not express demand after *demanded that*.", "The past indicative does not fit the subjunctive pattern.", "", "*Will be* adds future tense; the subjunctive uses the plain base form."]),
        QUIZ("Which is the correct passive of 'The students are painting the hall'?", ["The hall is painted by the students.", "The hall is being painted by the students.", "The hall was painted by the students.", "The hall has been painted by the students."], 1,
             "The active verb is the present continuous (*are painting*), so the passive is *is being painted*.", hint="Copy the tense: present continuous.",
             feedback=["This is the present simple.", "", "This is the past simple.", "This is the present perfect."]),
        PQ("Rewrite in the passive: 'They are building a new clinic near the market.'",
           "'A new clinic **is being built** near the market (by them).' The present continuous becomes *is/are being + past participle*; *by them* is normally left out."),
        PQ("Choose the correct form and explain: 'If I (was / were) the headmaster, I would introduce a reading hour.'",
           "**were**: an unreal condition uses the past subjunctive for every person. (*Was* is common in informal speech, but exam answers prefer *were*; check your textbook.)"),
        PQ("Explain why 'The ceremony was taken place in the hall' is wrong and correct it.",
           "*Take place* is intransitive, so it has no passive. Correct: 'The ceremony **took place** in the hall.'"),
        SUM("Three moods: indicative (fact), imperative (command), subjunctive (wish, demand, unreal).",
            "Present subjunctive: base verb after demand/insist/suggest + that; past subjunctive: were.",
            "Passive = be (in the active tense) + past participle.",
            "Intransitive and state verbs have no passive.",
            "Use the passive when the doer is unknown or unimportant; leave out the agent then."),
    ],
))

# ================================================================== 6. Reported speech
LESSONS.append(lesson(
    module=M, topic=T_REP,
    title="Reported speech: backshift, modals and reporting verbs",
    slug="enl2-reported-speech",
    minutes=22,
    summary="Reporting what was said changes tenses, pronouns and time words; questions lose their question order, commands become infinitives, and reporting verbs such as promise, deny and accuse each need their own pattern.",
    objectives=["Apply backshift of tenses and modals correctly", "Change pronouns and time and place words to suit the new speaker", "Report questions, commands, requests and suggestions",
                "Use reporting verbs (admit, deny, warn, promise, accuse, insist) with the right pattern"],
    key_concepts=["Backshift", "Reporting verb", "Reported question", "Reported command", "Time and place words"],
    blocks=[
        H("Introduction"),
        T("At O Level you changed *says* sentences into reported speech with a few simple rules. A Level goes further: the sentences contain modals, questions and commands, and the best answer often uses a **reporting verb** that carries the whole meaning: *She promised to come* is better than *She said that she would come*. This lesson builds on your O Level work and is the form tested in Paper 3 and Paper 1 Section C."),
        H("Backshift"),
        D("**Reported (indirect) speech** gives the meaning of what someone said without the exact words. When the reporting verb is in the past (*said, told, asked*), the tenses usually move one step back into the past. This is called **backshift**.", title="Definition"),
        CODE("DIRECT                       REPORTED\nsimple present  writes        simple past  wrote\npresent continuous is writing past continuous was writing\npresent perfect has written   past perfect  had written\nsimple past  wrote            past perfect  had written (or stays)\nwill  write                   would  write\ncan                           could\nmay                           might\nmust (obligation)             had to (or must)\nshould, would, could, might, ought to    do not change", "text", title="Backshift table"),
        T("**Pronouns, time and place words also change** because the speaker is now different or the time and place have moved: *I* becomes *he/she*; *now* becomes *then*; *today* becomes *that day*; *tomorrow* becomes *the next day* (or *the following day*); *yesterday* becomes *the day before* (or *the previous day*); *here* becomes *there*; *this* becomes *that*; *ago* becomes *before*."),
        T("**When there is no backshift.** If the reporting verb is in the present (*She says that she is tired*), nothing moves back. Backshift is also optional when the statement is still true or has just been made. For example, 'The teacher said that water boils at 100 degrees Celsius at sea level' is acceptable, and so is 'boiled'. Textbooks differ on how strict to be, and in an exam the safe answer is to backshift unless the question tells you otherwise: check your textbook. *Must* may stay as *must* in reported speech in some books (they say *had to* only for obligation); check your textbook."),
        EX("Worked example 1: statements", intro="Report: (a) 'I will see you tomorrow,' she said to me. (b) 'We have finished the project,' the students told the teacher.", steps=[
            S("(a) Change the pronouns and tense", text="*I* becomes *she*, *you* becomes *me*; *will* becomes *would*; *tomorrow* becomes *the next day*."),
            S("(a) Result", text="She told me that she **would** see me **the next day**."),
            S("(b) Change", text="*We* becomes *they*; present perfect becomes past perfect."),
            S("(b) Result", text="The students told the teacher that they **had finished** the project."),
        ]),
        H("Questions, commands and suggestions"),
        T("**Reported questions use statement order** (no question mark, no *do/does/did*). A yes/no question is introduced by *if* or *whether*; a wh-question keeps its question word."),
        EX("Worked example 2: questions", intro="Report: (a) 'Where do you live?' he asked me. (b) 'Did you finish the test?' the invigilator asked her.", steps=[
            S("(a) Wh-question: keep the question word, use statement order", text="He asked me where **I lived**. (not *where did I live* and not *where I live*)"),
            S("(b) Yes/no question: use if or whether, and the past perfect", text="The invigilator asked her **whether (or if) she had finished** the test."),
        ]),
        T("**Commands and requests** use *tell, order, ask, warn, advise* + object + *to*-infinitive. Negative commands use *not to*: 'Don't touch the wire,' the technician said → The technician **warned us not to touch** the wire."),
        T("**Suggestions and offers.** 'Let's go to the market' → She **suggested going** to the market (or *that we go / that we should go*). Do not write *suggested us to go*."),
        H("Reporting verbs and their patterns"),
        CODE("VERB                 PATTERN                            EXAMPLE\npromise, offer       + to + base verb                   He promised to bring the books.\nrefuse, threaten     + to + base verb                   She refused to sign.\nadvise, warn, invite + object + to + base verb          They advised him to wait.\nadmit, deny          + -ing (or that-clause)            He denied taking the phone.\napologise            for + -ing                         She apologised for being late.\naccuse               object + of + -ing                 They accused him of cheating.\nblame                object + for + -ing                She blamed him for losing it.\ninsist               on + -ing, or that-clause          He insisted on paying.\nsuggest              -ing, or that + (should) + verb    She suggested going early.", "text", title="Reporting-verb patterns"),
        EX("Worked example 3: choosing the reporting verb", intro="Report with one reporting verb: (a) 'I'll bring the books tomorrow,' Efe said. (b) 'You copied my answers!' the girl said to him. (c) 'I didn't take the money,' said the clerk.", steps=[
            S("(a) A promise", text="Efe **promised to bring** the books the next day."),
            S("(b) A charge", text="The girl **accused him of copying** her answers."),
            S("(c) A denial", text="The clerk **denied taking** the money (or *denied having taken* it)."),
        ]),
        MISTAKE("Keeping question order or the question mark", "Wrong: *He asked me where did I live?* Right: *He asked me where I lived.* A reported question is a statement inside a statement."),
        MISTAKE("Wrong pattern after a reporting verb", "Wrong: *She suggested me to go*, *He denied to take it*, *They accused him for stealing*. Right: *She suggested that I go*, *He denied taking it*, *They accused him of stealing*. Learn each verb with its pattern."),
        QUIZ("'Can you help me?' she asked. Which is the correct report?", ["She asked if I can help her.", "She asked me if I could help her.", "She asked me could I help her.", "She asked me that I could help her."], 1,
             "Yes/no question: *if* + backshifted modal (*could*), statement order, pronouns changed.", hint="Which option uses *if* and *could*?",
             feedback=["Cannot stay as *can* after the past reporting verb in a standard exam answer.", "", "Keeps question order.", "A yes/no question uses *if* or *whether*, not *that*."]),
        QUIZ("Which is the correct report of 'Don't leave your bags here,' the guard said to us?", ["The guard told us don't leave our bags there.", "The guard told us to not leave our bags there.", "The guard told us not to leave our bags there.", "The guard told us that we do not leave our bags there."], 2,
             "A negative command becomes *not to* + base verb; *here* becomes *there*; *your* becomes *our*.", hint="Use object + not to + verb.",
             feedback=["Direct speech is mixed into the report.", "The split infinitive 'to not leave' is disliked in formal writing: check your textbook.", "", "This is a statement, not a command."]),
        PQ("Report: 'I may visit Limbe next week,' said Ngwa.",
           "Ngwa said that he **might** visit Limbe **the following week**. (*May* becomes *might*; *next week* becomes *the following week*.)"),
        PQ("Report with a reporting verb: 'You should see a doctor,' my aunt said to me.",
           "My aunt **advised me to see** a doctor. (Advice: advise + object + to + base verb.)"),
        PQ("Report: 'Why haven't you done your homework?' the teacher asked Tabi.",
           "The teacher asked Tabi **why he hadn't done** his homework. (Present perfect becomes past perfect; statement order.)"),
        SUM("Backshift moves tenses and modals one step into the past when the reporting verb is past.",
            "Change pronouns, time words and place words to suit the new speaker.",
            "Reported questions have statement order; yes/no questions use if or whether.",
            "Commands and requests: tell/ask/warn + object + (not) to + verb.",
            "Reporting verbs carry meaning and fix the pattern: promise to, accuse of -ing, deny -ing."),
    ],
))

# ================================================================== 7. Gerunds and infinitives
LESSONS.append(lesson(
    module=M, topic=T_VERBAL,
    title="Gerunds and infinitives: which verb pattern follows which verb",
    slug="enl2-gerunds-infinitives",
    minutes=22,
    summary="Verbs, adjectives and prepositions decide whether the next verb is a gerund (-ing) or an infinitive (to + base); a few verbs take both with a change of meaning, and 'to' is sometimes a preposition followed by -ing.",
    objectives=["Define gerund and infinitive and give their functions", "Use the common verb patterns: enjoy + -ing, decide + to, make + bare infinitive", "Explain the change in meaning with stop, remember, forget, try and regret",
                "Recognise 'to' as a preposition (look forward to seeing)"],
    key_concepts=["Gerund", "Infinitive", "Bare infinitive", "Verb pattern", "Preposition + -ing"],
    blocks=[
        H("Introduction"),
        T("English has three 'verbals': forms made from verbs that do not act as the main verb of a sentence. They are the **gerund**, the **infinitive** and the **participle**. This lesson covers the first two; participles come next. In Paper 1 Section C, a typical item is: 'She avoided ______ the question. (to answer / answering / answer / answered)'. Only knowing the pattern settles it."),
        H("Definitions"),
        D("A **gerund** is the *-ing* form of a verb used as a noun: *Swimming is good exercise.* An **infinitive** is the base form of the verb, usually with *to*: *to swim*. The infinitive without *to* is called the **bare infinitive**: *She can swim.*", title="Definition"),
        T("A gerund can be a subject (*Reading improves vocabulary*), an object (*He enjoys reading*), a complement (*My hobby is reading*) or follow a preposition (*She is good at reading*). An infinitive can express purpose (*She went to the market to buy fish*), follow an adjective (*It is easy to learn*) or follow certain verbs (*I want to go*)."),
        H("Verbs followed by a gerund or an infinitive"),
        CODE("+ GERUND (-ing)                 + INFINITIVE (to + base)\nenjoy, avoid, finish, mind      want, decide, hope, plan\nsuggest, consider, practise     promise, refuse, agree, offer\nrisk, deny, admit, postpone     manage, afford, fail, learn\nkeep, miss, imagine             expect, seem, appear, tend\ncan't help, can't stand         would like, would prefer", "text", title="Two lists to learn"),
        T("Examples: *She finished writing the report. They decided to leave early. He avoided answering the question. The company cannot afford to pay more.* Each pattern simply has to be learnt; there is no rule that predicts it."),
        T("**Both patterns with little difference:** *begin, start, continue, like, love, hate, prefer.* 'It started raining' = 'It started to rain.'"),
        KEY("Both patterns with a change in meaning", "The two forms are not interchangeable here.", cards=[
            ["stop", "*stop + -ing* = end the action: *She stopped buying bread* (no longer buys). *stop + to* = stop in order to do: *She stopped to buy bread* (paused her journey)."],
            ["remember / forget", "*+ -ing* = a past action recalled: *I remember locking the door* (I did lock it). *+ to* = a duty: *Remember to lock the door.*"],
            ["try", "*try + -ing* = experiment: *Try pressing the red button.* *try + to* = make an effort: *She tried to open the door* (it may not have opened)."],
            ["regret", "*regret + -ing* = sorry about the past: *I regret telling him.* *regret + to* (formal) = sorry about what I am now saying: *We regret to inform you...*"]]),
        H("Prepositions take the gerund"),
        T("After a preposition, use a gerund: *interested in learning, good at drawing, tired of waiting, instead of complaining, before leaving, by working hard.* Be careful with **to**: in some expressions it is a preposition, so a gerund follows. *I look forward to seeing you. She is used to getting up early. He objects to paying twice. I am committed to improving.* Test: if you can put a noun there, *to* is a preposition (*I look forward to the holidays*)."),
        H("Bare infinitive"),
        T("The bare infinitive follows modals (*She must go*), *let* and *make* with an object (*The teacher let us leave. The heat made him sleep.*), *had better* and *would rather*. With *help*, both are correct: *help us (to) carry*. In the passive, *to* returns: *We were made to wait.* After the perception verbs *see, hear, watch*, a bare infinitive means the whole action was seen: *I saw him cross the road* (from start to end); the -ing form means part of the action: *I saw him crossing the road.*"),
        EX("Worked example 1: choosing the pattern", intro="Choose the correct word: (a) 'The committee agreed (to pay / paying) all the debts.' (b) 'The manager suggested (to close / closing) the shop early.'", steps=[
            S("(a) agree", text="*Agree* takes an infinitive: **to pay**."),
            S("(b) suggest", text="*Suggest* takes a gerund: **closing**. (*Suggested to close* is an error.)"),
        ]),
        EX("Worked example 2: stop, remember, forget", intro="Explain the difference: (a) 'I forgot to post the letter.' (b) 'I forgot posting the letter.'", steps=[
            S("(a) forget + to", text="I did not post it; I failed to remember my duty."),
            S("(b) forget + -ing", text="I posted it, but I do not remember doing so."),
        ]),
        EX("Worked example 3: is 'to' an infinitive marker or a preposition?", intro="Complete: 'We look forward to (meet / meeting) you.'", steps=[
            S("Apply the test", text="Can we say *We look forward to the meeting*? Yes, so *to* is a preposition."),
            S("Choose a gerund", text="'We look forward to **meeting** you.'"),
        ]),
        T("**Two points on which books differ.** The *split infinitive* (*to quickly leave*) is accepted by most modern books but some prefer *to leave quickly*: check your textbook. Before a gerund, formal English uses the possessive (*I dislike his shouting*), though *him shouting* is common in speech: check your textbook."),
        MISTAKE("Using the infinitive after a gerund-verb", "Wrong: *He avoided to answer*, *She enjoys to dance*, *They suggested to leave*, *I look forward to see you*. Right: *avoided answering*, *enjoys dancing*, *suggested leaving*, *look forward to seeing*."),
        MISTAKE("Gerund after a modal", "Wrong: *She can swimming*, *You must to go*. A modal is followed by the bare infinitive: *She can swim.*"),
        QUIZ("'They have postponed ______ the meeting until Friday.'", ["to hold", "holding", "hold", "held"], 1,
             "*Postpone* takes a gerund: *postponed holding*.", hint="Is *postpone* in the gerund list or the infinitive list?",
             feedback=["*Postpone* is not followed by an infinitive.", "", "The bare infinitive does not follow this verb.", "The past participle makes no sense after *postponed*."]),
        QUIZ("'She stopped ______ the market stall because she saw a friend.'", ["to talk to", "talking to", "talk to", "talked to"], 0,
             "*Stopped to talk* = paused in order to talk. *Stopped talking* would mean she no longer talked.", hint="Did she pause in order to do something?",
             feedback=["", "That would mean she ended a conversation.", "Bare infinitive does not follow *stopped* here.", "Past tense does not fit the sentence pattern."]),
        PQ("Correct the errors: (a) 'My brother enjoys to play football.' (b) 'I am looking forward to see my cousins.'",
           "(a) '...enjoys **playing** football.' *Enjoy* + gerund. (b) '...looking forward to **seeing** my cousins.' *To* is a preposition here."),
        PQ("Explain the difference between 'I remember meeting the Governor' and 'Remember to meet the Governor'.",
           "The first recalls a past event that happened (meeting). The second is a reminder of a duty not yet done (meet)."),
        PQ("A girl wants to become a doctor and does not give up that dream. Write one sentence about her with *refuse* and one with *keep*.",
           "Model: 'She **refused to give up** her dream of becoming a doctor.' / 'She **kept working** towards her dream.' *Refuse* + infinitive; *keep* + gerund."),
        SUM("A gerund is -ing used as a noun; an infinitive is the base verb, usually with to.",
            "Learn the lists: enjoy/avoid/finish/suggest/postpone + -ing; want/decide/hope/promise/manage + to.",
            "Stop, remember, forget, try, regret change meaning with -ing or to.",
            "After a preposition use -ing, including 'look forward to', 'be used to', 'object to'.",
            "After modals, let and make use the bare infinitive."),
    ],
))

# ================================================================== 8. Participles
LESSONS.append(lesson(
    module=M, topic=T_VERBAL,
    title="Participles and participle phrases",
    slug="enl2-participles-phrases",
    minutes=21,
    summary="Present participles (-ing), past participles (-ed or irregular) and perfect participles (having + past participle) can work as adjectives or begin phrases that join sentences; the phrase must belong to the subject that follows.",
    objectives=["Tell present, past and perfect participles apart and say which is active or passive", "Use -ing and -ed adjectives correctly (boring/bored)", "Join sentences with a participle phrase and keep the same subject",
                "Distinguish a gerund from a present participle by its function"],
    key_concepts=["Present participle", "Past participle", "Perfect participle", "Participle phrase", "Gerund v participle"],
    blocks=[
        H("Introduction"),
        T("Compare these: 'The students were tired.' and 'Tired, the students went home.' and 'Having finished the exam, the students went home.' The second and third use **participles** to join ideas in a short and elegant way. At A Level, Paper 1 and Paper 3 test both the forms and the rule that the participle phrase must fit the subject that follows it."),
        H("The three participles"),
        D("A **participle** is a verb form used as an adjective or to introduce a phrase. The **present participle** ends in *-ing* (*walking*) and is active. The **past participle** ends in *-ed* or is irregular (*walked, broken, written*) and is usually passive in meaning. The **perfect participle** is *having* + past participle (*having walked*) and shows that its action finished first.", title="Definition"),
        CODE("Present   (active, at the same time)   Walking home, she met her uncle.\nPast      (passive)                        Built in 1992, the bridge is still strong.\nPerfect   (earlier action)                 Having finished the test, she left.\nPerfect passive                            Having been warned, the driver slowed down.", "text", title="Participle phrases"),
        H("-ing and -ed adjectives"),
        T("Many feelings have two adjective forms. The **-ing** form describes the cause; the **-ed** form describes the person who has the feeling. *The lecture was boring. The students were bored.* *The result was surprising. We were surprised.* *The film was exciting. The children were excited.*"),
        H("Joining sentences with participle phrases"),
        T("A participle phrase can replace a short clause of time, reason or cause. It saves words, and the **understood subject of the phrase is the subject of the main clause**."),
        EX("Worked example 1: present participle", intro="Join: 'Eka walked to school. She met her cousin.'", steps=[
            S("Choose the participle", text="Walking to school is the first action; both are by Eka."),
            S("Write the phrase and keep the subject", text="'**Walking** to school, Eka met her cousin.' The phrase has no subject of its own; *Eka* is understood."),
        ]),
        EX("Worked example 2: perfect participle", intro="Join: 'The farmers had harvested the cassava. They took it to the market.'", steps=[
            S("The first action was finished before the second", text="Use *having* + past participle."),
            S("Join", text="'**Having harvested** the cassava, the farmers took it to the market.'"),
        ]),
        EX("Worked example 3: past participle", intro="Join: 'The bridge was damaged by floods. It remained closed for a month.'", steps=[
            S("The bridge received the action: a passive meaning", text="Use the past participle."),
            S("Join", text="'**Damaged by floods**, the bridge remained closed for a month.'"),
        ]),
        T("Participles can also replace a relative clause: 'The man **standing** at the gate is my uncle' (= who is standing). 'The books **left** on the bus were returned' (= which were left)."),
        T("An **absolute construction** has its own subject: 'The rain having stopped, we continued the match.' It is formal and rare. Do not confuse it with a dangling participle: its subject (*the rain*) is stated."),
        KEY("Gerund or present participle?", "Both end in -ing; look at the job.", cards=[
            ["Gerund (noun)", "*Swimming is fun. She is afraid of flying.* It can be the subject or follow a preposition."],
            ["Participle (adjective/verb)", "*A swimming pool; the barking dog; Seeing the teacher, he stood.* It describes a noun or begins a phrase."]]),
        MISTAKE("Wrong participle for feelings", "Wrong: *I am very boring* (means you are a boring person), *The match was excited*. Right: *I am very bored. The match was exciting.* The *-ing* word describes the cause; the *-ed* word describes the person."),
        MISTAKE("Wrong subject for the phrase", "Wrong: *Walking to school, the rain started.* (the rain was not walking). Right: *Walking to school, Eka was caught in the rain.* The full rule is in the lesson on dangling modifiers."),
        QUIZ("'______ the form, he handed it to the clerk.'", ["Completing", "Having completed", "Complete", "To complete"], 1,
             "Completing the form came first, so the perfect participle: *Having completed*.", hint="Which action is first?",
             feedback=["The present participle would suggest that the two actions happened at the same time.", "", "A base verb cannot begin the phrase here.", "An infinitive of purpose changes the meaning."]),
        QUIZ("Which sentence uses the correct adjective?", ["The long speech was tiring.", "The long speech was tired.", "I felt very tiring after the speech.", "The long speech made everyone tiring."], 0,
             "The speech causes the tiredness, so *tiring*. A person who feels it is *tired*.", hint="Cause or feeling?",
             feedback=["", "A speech cannot feel tired.", "A person who feels the effect is *tired*, not *tiring*.", "Everyone feels the effect, so the word should be *tired*."]),
        PQ("Join with a participle: 'Nkeng saw the police car. He slowed down.'",
           "'**Seeing** the police car, Nkeng slowed down.' (Present participle: the actions are close together.)"),
        PQ("Join with a participle: 'The students had written the exam. They went to the playground.'",
           "'**Having written** the exam, the students went to the playground.' (Perfect participle: earlier action.)"),
        PQ("State whether *swimming* is a gerund or a participle: (a) 'Swimming keeps you fit.' (b) 'The swimming champion is from Kribi.'",
           "(a) **Gerund**: it is the subject (a noun job). (b) **Participle**: it describes *champion* (an adjective job)."),
        SUM("Present participle (-ing): active; past participle: passive; perfect participle (having + pp): earlier action.",
            "-ing adjectives describe causes; -ed adjectives describe people who feel.",
            "A participle phrase must refer to the subject of the main clause.",
            "Gerund = noun job; participle = adjective or phrase-opening job."),
    ],
))

# ================================================================== 9. Pronouns
LESSONS.append(lesson(
    module=M, topic=T_PRON,
    title="Pronouns: case, reflexives, who and whom, and when to omit",
    slug="enl2-pronouns-forms-omission",
    minutes=22,
    summary="Pronouns change form with their job (I/me, who/whom, my/mine); reflexive pronouns have strict uses, indefinite pronouns take singular verbs, and some pronouns must be left out or never doubled.",
    objectives=["Choose the correct pronoun case in compound phrases: 'between you and me', 'He and I'", "Use who and whom, and reflexive and reciprocal pronouns correctly",
                "Distinguish possessive adjectives from possessive pronouns", "Leave out pronouns that must be omitted, and avoid double subjects and missing subjects"],
    key_concepts=["Subject and object case", "Reflexive pronoun", "Possessive pronoun", "Indefinite pronoun", "Omission", "Double subject"],
    blocks=[
        H("Introduction"),
        T("The O Level lesson introduced the kinds of pronoun. At A Level, the questions are about choosing between forms that look similar: *I or me, who or whom, myself or me, its or it's.* Section C often hides the choice in a compound ('Between you and ___') or in a long sentence."),
        H("Subject and object case"),
        CODE("SUBJECT   I    you   he    she   it   we   they   who\nOBJECT    me   you   him   her   it   us   them   whom\nPOSS ADJ  my   your  his   her   its  our  their  whose\nPOSS PRON mine yours his   hers  --   ours theirs  --\nREFLEXIVE myself yourself himself herself itself ourselves themselves", "text", title="The pronoun table"),
        T("**Use the subject form when the pronoun is a subject** (*She and I are friends*) **and the object form when it is an object of a verb or preposition** (*She told him and me*; *between you and me*; *for her and them*). The easiest test with a compound: **remove the other person**. 'The teacher praised Ngu and (I / me)': remove *Ngu* and you get 'praised me', so **me**."),
        T("**Than and as.** In 'She is taller than I', formal English reads *than I (am)*; in speech 'than me' is common. After *be*, 'It is I' is formal and 'It is me' is common. These are points where textbooks differ: check your textbook, and in an exam follow the form your book gives."),
        H("Who and whom"),
        T("**Who** is for the subject and **whom** for the object, especially after a preposition. 'The woman **who** teaches us' (she teaches: subject). 'The woman **whom** we met' (we met her: object). 'To whom did you give it?' (formal). In speech and many modern books, *who* replaces *whom* when it is not after a preposition; Paper 1 tends to follow the formal rule, so check your textbook."),
        EX("Worked example 1: who or whom", intro="Choose: (a) 'The doctor (who / whom) examined the child was calm.' (b) 'The candidate (who / whom) the panel interviewed first was a woman.'", steps=[
            S("(a) Replace the pronoun with he/him", text="'He examined the child': the pronoun is the subject, so **who**."),
            S("(b) Replace with he/him", text="'The panel interviewed him': the pronoun is the object, so **whom**."),
        ]),
        H("Reflexive and reciprocal pronouns"),
        D("A **reflexive pronoun** (*myself, herself...*) is used when the object of the verb is the same person as the subject: *She cut herself.* It can also be used for emphasis: *I made it myself.* A **reciprocal pronoun** (*each other, one another*) shows two or more people doing the same to each other: *The twins help each other.*", title="Definition"),
        T("Do not use a reflexive just to sound formal. Wrong: *Please send the report to John or myself.* Right: *...to John or me.* After *by*, a reflexive means alone: *She did it by herself.* (Some books keep *each other* for two and *one another* for more than two; others do not: check your textbook.)"),
        H("Possessives, indefinite pronouns and reference"),
        T("**My/your/his** (possessive adjectives) come before a noun: *my book*. **Mine/yours/hers** stand alone: *The book is mine.* Note *a friend of mine* (not *a friend of me*) and *its* (belonging to it) versus *it's* (it is or it has)."),
        T("**Everyone, everybody, someone, nobody, each, either, neither** take singular verbs: *Everyone is here.* A later pronoun may be *his or her* or the singular *they/their*; the latter is common in speech and increasingly accepted: check your textbook."),
        T("**Clear reference.** A pronoun must have one clear noun it refers to. 'When Ada met Efe, she was angry' does not say who was angry. Repeat the name or rewrite."),
        H("Leaving pronouns out, and not doubling them"),
        T("**A relative pronoun can be omitted when it is the object** of its own clause: 'The book (that) I bought is expensive.' It cannot be omitted when it is the subject: 'The book *that* is on the table is mine' (not 'The book is on the table is mine')."),
        T("English needs a subject in every clause, so a dummy *it* or *there* is used: *It is raining. There are many people.* Wrong: *Is raining.* Also never repeat the subject: *My brother he is a teacher* is wrong; write *My brother is a teacher.* A pronoun that repeats the object is also wrong: *The book that I bought it is expensive* should be *The book that I bought is expensive.*"),
        EX("Worked example 2: choosing the form", intro="Choose the correct pronoun: 'The headmistress gave the prizes to Ayo and (I / me / myself).'", steps=[
            S("Remove the other person", text="'gave the prizes to ___': after a preposition, use the object form."),
            S("Reject the reflexive", text="The subject (the headmistress) is not the same as the object, so not *myself*."),
            S("Answer", text="'...to Ayo and **me**.'"),
        ]),
        EX("Worked example 3: correcting the sentence", intro="Correct: 'The girl who I met she is a nurse.'", steps=[
            S("Double subject", text="Remove *she*."),
            S("Omit or keep the relative pronoun", text="*Who* is the object of *met*, so it may be omitted or written as *whom*."),
            S("Result", text="'The girl **whom** I met is a nurse.' / 'The girl I met is a nurse.'"),
        ]),
        MISTAKE("'Me and him went'", "Subjects take the subject form: *He and I went.* (By courtesy, the other person comes first.) Objects take the object form: *She asked him and me.*"),
        MISTAKE("Reflexive in place of me", "Wrong: *The manager asked Efe and myself to wait.* Right: *...Efe and me...* Use *myself* only when *I* is the subject, or for emphasis."),
        QUIZ("'The reward was shared between Nina and ______.'", ["I", "me", "myself", "mine"], 1,
             "After the preposition *between*, use the object form: *me*.", hint="Remove *Nina and*. Would you say 'between I'?",
             feedback=["*I* is the subject form.", "", "No reflexive is needed here; the subject is *the reward*.", "*Mine* is a possessive pronoun."]),
        QUIZ("'Everyone ______ invited to the party last night.'", ["were", "was", "are", "have been"], 1,
             "*Everyone* is grammatically singular. The sentence is in the past (*last night*), so *was*.", hint="Singular or plural verb? Past or present?",
             feedback=["*Were* is plural.", "", "*Are* is present tense, but the time is *last night*.", "The present perfect does not go with *last night*."]),
        PQ("Correct each sentence: (a) 'Me and my cousin visited Kribi.' (b) 'The principal thanked myself and the teachers.'",
           "(a) '**My cousin and I** visited Kribi.' (subject form). (b) 'The principal thanked **me** and the teachers.' (not a reflexive)."),
        PQ("Why is 'The man who lives next door he is a driver' wrong? Correct it.",
           "The subject is doubled (*who/the man* and *he*). Correct: 'The man who lives next door is a driver.'"),
        PQ("Which pronoun can be omitted? (a) 'The film that I saw was long.' (b) 'The film that won the prize was long.'",
           "In (a) *that* is the object of *saw* and can be omitted. In (b) *that* is the subject of *won* and cannot be."),
        SUM("Use subject form for subjects, object form for objects and after prepositions; test by removing the other person.",
            "Who = subject; whom = object (formal, especially after a preposition).",
            "Reflexives are for the same person as the subject, or emphasis.",
            "Everyone, someone, nobody are singular.",
            "Omit an object relative pronoun if you wish, never a subject one; never double a subject."),
    ],
))

# ================================================================== 10. Determiners
LESSONS.append(lesson(
    module=M, topic=T_PRON,
    title="Determiners: articles, numerals, possessives and quantifiers",
    slug="enl2-determiners",
    minutes=22,
    summary="Determiners (a/an/the, numbers, my/your, this/that, each/every, some/any, both/either) come before nouns and limit them; the choice depends on whether the noun is count or non-count, specific or general.",
    objectives=["Choose a, an, the or no article correctly", "Use numerals and 'hundred, thousand, million' correctly", "Use each, every, both, either, neither, all, another and other with the right noun",
                "Place determiners in the correct order before a noun"],
    key_concepts=["Determiner", "Indefinite and definite article", "Zero article", "Distributive determiners", "Determiner order"],
    blocks=[
        H("Introduction"),
        T("A **determiner** is a small word placed before a noun to say which one or how many. English cannot usually use a singular count noun without one: we cannot say *I bought book*; we must say *a book, the book, my book, this book*. Determiners are tested in nearly every Paper 1 Section C because small words are easy to get wrong."),
        D("**Determiners** include: articles (*a, an, the*), demonstratives (*this, that, these, those*), possessive adjectives (*my, your, his...*), numerals (*one, two, first, second*), and quantifiers (*some, any, much, many, few, each, every, both, all, either, neither, another, other*).", title="Definition"),
        H("Articles"),
        KEY("A, an, the, or nothing", "Three questions decide.", cards=[
            ["a / an", "Singular count noun, first mention or any one: *She bought a phone.* Use *an* before a vowel sound, not a vowel letter: *an hour, an MP* but *a university, a European, a one-way street*."],
            ["the", "A noun that both speaker and listener know: second mention (*The phone was cheap*), unique (*the sun, the equator*), made specific (*the girl in the red dress*), superlatives (*the best result*), and ordinals (*the second floor*)."],
            ["no article (zero)", "Plural and non-count nouns in a general sense: *Books are expensive. Honesty matters. Life is short.*"]]),
        T("**Places and institutions.** With *school, church, hospital, prison, university, bed, court* we omit *the* when we mean the activity: *She goes to school. He is in hospital. They went to church.* We use *the* for the building: *The school is near the market. I visited a friend in the hospital.* (British English says *in hospital* where American usage says *in the hospital*: check your textbook.)"),
        T("**Proper names.** No article for most countries, towns, mountains and lakes: *Cameroon, Yaounde, Mount Cameroon, Lake Chad.* Use *the* for rivers, oceans, deserts and plural names: *the Sanaga, the Atlantic, the Sahara, the United States, the Gambia*."),
        H("Numerals"),
        T("Cardinal numbers (*one, two*) answer how many; ordinal numbers (*first, second*) show position. After a number, *hundred, thousand* and *million* take no -s: *three hundred students, five thousand francs.* Use the plural with *of* when the number is not exact: *hundreds of students, thousands of people.* Write *a hundred and twenty* (British) or *a hundred twenty* (also used): check your textbook."),
        H("Each, every, both, either, neither, all"),
        CODE("each / every / either / neither   + SINGULAR noun   each student, every day, either road\nboth                              + PLURAL noun     both students\nall                               + plural or non-count   all students, all water\nanother                           + singular count noun   another chair\nother(s)                          other chairs / the others", "text", title="Distributive determiners"),
        T("*Each* and *every* take a singular verb: *Each pupil has a book.* *Both* means two; *either* and *neither* refer to one of two. For three or more, use *any/none*: 'Neither of the two roads is safe' but 'None of the three roads is safe.' *Another* means one more (*another cup*); *the other* means the remaining one of two (*one hand ... the other*); *others* stands alone (*Some agree; others do not*)."),
        T("**Determiner order:** predeterminer (*all, both, half*) → determiner (*the, my, these*) → number → adjective → noun. Natural examples: *both my brothers, all these students, the first two days, half the money, my two tired cousins.*"),
        EX("Worked example 1: articles", intro="Fill the gaps with a, an, the or nothing: 'Ndi is ___ engineer. He works at ___ hospital in ___ Bamenda. ___ hospital is ___ biggest in the region, and ___ doctors there are very kind.'", steps=[
            S("Ndi is ___ engineer", text="First mention, singular, vowel sound: **an**."),
            S("at ___ hospital in ___ Bamenda", text="First mention of a specific hospital: **a**. *Bamenda* is a town: **no article**."),
            S("___ hospital is ___ biggest", text="Second mention: **The**; superlative: **the**."),
            S("___ doctors there", text="Specific doctors (there): **the**."),
        ]),
        EX("Worked example 2: each, every, both, either", intro="Choose: (a) 'Each of the (student / students) (has / have) a locker.' (b) '(Both / Either) of my parents are teachers.'", steps=[
            S("(a)", text="*Each of the* + plural noun, but the verb is singular: 'Each of the **students has** a locker.'"),
            S("(b)", text="Both are teachers, so *both*; *either* means one of two: '**Both** of my parents are teachers.'"),
        ]),
        MISTAKE("A before a vowel sound", "The rule depends on sound, not spelling: *an hour* (silent h), *a uniform* (starts with the sound 'yoo'), *an umbrella*, *a one-year course*."),
        MISTAKE("The with general ideas", "Wrong: *The honesty is important. The life is short. I like the football.* Right: *Honesty is important. Life is short. I like football.*"),
        MISTAKE("Plural -s after a number, and 'each students'", "Wrong: *two hundreds students*, *each students*, *every students*, *the both brothers*. Right: *two hundred students*, *each student*, *every student*, *both brothers*."),
        QUIZ("'My uncle is ______ honest man.'", ["a", "an", "the", "no article"], 1,
             "*Honest* begins with a vowel sound (h is silent): *an honest man*.", hint="Say the word aloud. What is the first sound?",
             feedback=["*A* is used before a consonant sound.", "", "*The* would refer to a particular man already known.", "A singular count noun needs a determiner."]),
        QUIZ("Which sentence is correct?", ["Every students received a certificate.", "Each of the students received a certificate.", "Both of the three students received a certificate.", "All students was given a certificate."], 1,
             "*Each of the* + plural noun, with a singular verb. *Every* needs a singular noun; *both* means two; *all students* needs a plural verb.", hint="Check the noun after every/each and the verb.",
             feedback=["*Every* needs a singular noun: *every student*.", "", "*Both* refers to two, not three.", "*All students* takes a plural verb: *were given*."]),
        PQ("Correct: 'The life is full of the surprises, but the honesty is always the best policy.'",
           "'**Life** is full of **surprises**, but **honesty** is always the best policy.' General ideas and plural nouns used in a general sense take no article. *The best policy* keeps its *the* because of the superlative."),
        PQ("Explain the difference: (a) 'She goes to school by bus.' (b) 'She went to the school to meet the principal.'",
           "(a) *School* here is the activity (she is a pupil): no article. (b) *The school* is the building she visited for a visit: *the* is used."),
        PQ("Choose the correct form: 'Cameroon exported about three (hundred / hundreds) tonnes of cocoa to (a / an) European country.'",
           "'three **hundred** tonnes' (no -s after an exact number) and '**a** European country' (the word begins with a *y* sound). (Figures are invented for teaching.)"),
        SUM("A/an with first-mention singular count nouns; the for known or unique; nothing for general plural or non-count nouns.",
            "A or an depends on the sound that follows.",
            "Each, every, either, neither + singular noun; both + plural noun (two things).",
            "Hundred and thousand take no -s after an exact number.",
            "Order: all/both/half, then the/my/these, then numbers, then adjectives."),
    ],
))

# ================================================================== 11. Sentence types
LESSONS.append(lesson(
    module=M, topic=T_STYPE,
    title="Sentence types: simple, compound, complex and compound-complex",
    slug="enl2-sentence-types",
    minutes=21,
    summary="A sentence is classified by its clauses: one independent clause (simple), two or more independent clauses (compound), one independent plus a dependent clause (complex), or both kinds together (compound-complex).",
    objectives=["Define a clause and tell independent from dependent clauses", "Classify any sentence as simple, compound, complex or compound-complex", "Combine short sentences into a target type using coordinators and subordinators",
                "Use conjunctive adverbs (however, therefore) with the correct punctuation"],
    key_concepts=["Clause", "Independent clause", "Dependent (subordinate) clause", "Coordinating conjunction", "Subordinating conjunction", "Conjunctive adverb"],
    blocks=[
        H("Introduction"),
        T("Good writers vary the length and shape of their sentences. The Board's syllabus lists four types, and Paper 1 and Paper 3 ask you to name them or to build them. The method never changes: **count the clauses, then see how they are joined.**"),
        H("Clauses"),
        D("A **clause** is a group of words with its own subject and finite verb. An **independent (main) clause** makes complete sense alone: *The rain stopped.* A **dependent (subordinate) clause** cannot stand alone because it begins with a word such as *because, although, when, who*: *because the rain stopped*. A **phrase** has no subject and verb together: *after the rain*.", title="Definition"),
        H("The four types"),
        CODE("TYPE                CLAUSES                           EXAMPLE\nSimple              1 independent                     The farmers sold their maize.\nCompound            2+ independent                    The farmers sold their maize, and the traders bought it.\nComplex             1 independent + 1+ dependent      Because prices were high, the farmers sold their maize.\nCompound-complex    2+ independent + 1+ dependent     Because prices were high, the farmers sold their maize, and the traders bought it.", "text", title="Four sentence types"),
        T("A **simple sentence** can still be long: *The farmers and the traders in the old market sold and bought maize and beans all morning.* It has one subject group and one predicate group, so it is simple. 'She opened the window **and** looked outside' is also simple: one subject (*she*) with a compound predicate."),
        H("Joining clauses"),
        KEY("Two ways of joining", "The joining word decides the type.", cards=[
            ["Coordination: equal clauses", "The seven coordinating conjunctions: *for, and, nor, but, or, yet, so* (the word FANBOYS helps memory). Put a comma before the conjunction when it joins two full clauses. *Efe likes football, but her brother prefers athletics.*"],
            ["Subordination: one clause depends on another", "Subordinating conjunctions: *because, since, although, though, if, unless, while, whereas, when, after, before, until, so that*; relative words *who, which, that, whose*; and *that* for statements. *Although it rained, the match continued.*"]]),
        T("**Conjunctive adverbs** (*however, therefore, moreover, nevertheless, consequently, otherwise, thus*) join two independent clauses with a **semicolon** before them and a comma after: *The road was flooded; however, the bus still left.* Using only a comma creates a comma splice, which is an error (see the lesson on run-on sentences)."),
        EX("Worked example 1: classification", intro="Classify: (a) 'The students who revised carefully passed the test.' (b) 'She opened the window and looked outside.' (c) 'When the rain stopped, the children went out, and the road was soon full of laughter.'", steps=[
            S("(a) Count clauses", text="*The students passed the test* (independent) with *who revised carefully* (dependent, describing students). One of each: **complex**."),
            S("(b) Count subjects and verbs", text="One subject (*she*) with two verbs (*opened, looked*). One clause: **simple**."),
            S("(c) Count clauses", text="*When the rain stopped* (dependent); *the children went out* (independent); *the road was soon full of laughter* (independent). **Compound-complex**."),
        ]),
        EX("Worked example 2: building a target type", intro="Combine 'The bridge was closed. The traffic moved slowly.' into (a) a compound sentence (b) a complex sentence.", steps=[
            S("(a) Equal clauses with a coordinator", text="'The bridge was closed, **so** the traffic moved slowly.'"),
            S("(b) Make one clause depend on the other", text="'**Because** the bridge was closed, the traffic moved slowly.'"),
        ], check=r"\text{(a) 2 independent clauses};\ \text{(b) 1 independent + 1 dependent}"),
        TIP("When you are asked to 'combine', check that the result keeps all the information and the original meaning. Changing 'but' to 'and' changes the meaning."),
        MISTAKE("Calling a sentence compound because it has 'and'", "*And* can join words or phrases (*tea and bread*) or two verbs with the same subject. Only when it joins two full clauses (each with its own subject and verb) is the sentence compound."),
        MISTAKE("Comma splice with however", "Wrong: *The test was hard, however, most students passed.* Right: *The test was hard; however, most students passed.* or *The test was hard. However, most students passed.* or *The test was hard, but most students passed.*"),
        QUIZ("'Although she was tired, she finished the report, and she sent it at once.' This sentence is", ["simple", "compound", "complex", "compound-complex"], 3,
             "One dependent clause (*Although she was tired*) and two independent clauses: compound-complex.", hint="Count the clauses, then ask which are dependent.",
             feedback=["It has more than one clause.", "It has a dependent clause as well.", "It has two independent clauses, not one.", ""]),
        QUIZ("Which sentence is complex?", ["The sun set, and the market closed.", "The market closed after the sun set.", "The market closed.", "The sun set; the market closed."], 1,
             "*After the sun set* is a dependent clause attached to *The market closed*: complex.", hint="Find the sentence with a subordinating conjunction.",
             feedback=["Two independent clauses joined by and: compound.", "", "One clause: simple.", "Two independent clauses with a semicolon: compound."]),
        PQ("Classify: 'Ngu studied hard, but he failed the first paper because he panicked.'",
           "*Ngu studied hard* (independent), *he failed the first paper* (independent), *because he panicked* (dependent). **Compound-complex**."),
        PQ("Combine into one complex sentence: 'The clinic opened. Fewer children fell ill.'",
           "'**After** the clinic opened, fewer children fell ill.' or 'Fewer children fell ill **because** the clinic opened.' (The meaning of cause or time must fit the facts you are given.)"),
        PQ("Rewrite with a conjunctive adverb and the right punctuation: 'The team trained daily. They lost the final.'",
           "'The team trained daily; **however**, they lost the final.'"),
        SUM("Simple: one independent clause. Compound: two or more independent clauses.",
            "Complex: one independent clause with one or more dependent clauses.",
            "Compound-complex: at least two independent clauses and one dependent clause.",
            "Coordinate with FANBOYS; subordinate with because, although, who and similar words.",
            "A conjunctive adverb needs a semicolon or a full stop, never a comma alone."),
    ],
))

# ================================================================== 12. Agreement
LESSONS.append(lesson(
    module=M, topic=T_AGR,
    title="Agreement: difficult subjects and pronoun-antecedent agreement",
    slug="enl2-agreement-difficult-cases",
    minutes=21,
    summary="A verb agrees with its true subject, not the nearest noun; either/or and neither/nor, collective nouns, 'a number of' and 'one of the ... who' need special care, and a pronoun must agree with its antecedent.",
    objectives=["Find the true subject when phrases come between subject and verb", "Apply proximity agreement with either/or and neither/nor", "Handle 'a number of / the number of', amounts, titles and 'one of the ... who'",
                "Make pronouns agree with collective and indefinite antecedents"],
    key_concepts=["Subject-verb agreement", "True subject", "Proximity rule", "Collective noun", "Antecedent"],
    blocks=[
        H("Introduction"),
        T("You studied the basic concord rules at O Level (the verb agrees with its subject in number). Section C tests the cases where the nearest noun is a trap. The method: **find the verb, ask 'who or what does it?', then ignore everything inside phrases that come between the subject and the verb.**"),
        H("Cases to master"),
        KEY("Subject separated from its verb", "Ignore interrupting phrases.", cards=[
            ["Prepositional phrases", "*The box of old books **was** heavy.* The subject is *box*, not *books*."],
            ["With, together with, as well as, along with", "These do not make the subject plural. *The teacher, together with her pupils, **is** going on a trip.*"],
            ["More than one", "*More than one candidate **has** complained.* (singular)"]]),
        T("**Either ... or, neither ... nor, not only ... but also.** The verb agrees with the **nearer** subject (proximity). 'Neither the principal nor the students **were** present.' 'Neither the students nor the principal **was** present.' 'Either my brothers or my sister **is** coming.'"),
        T("**A number of / the number of.** *A number of* means 'several' and takes a plural verb: *A number of students **are** absent.* *The number of* is a count and takes a singular verb: *The number of students absent **is** ten.*"),
        T("**Collective nouns** (*committee, team, class, family, staff, government*). In British English, a collective noun takes a singular verb when the group acts as one (*The committee **has** announced its decision*) and a plural verb when the members act separately (*The committee **are** divided*). American English prefers the singular. Many exam books accept the singular in every case: check your textbook. *Police* and *people* are always plural: *The police **are** looking for him.*"),
        T("**Amounts and titles.** A sum, distance or period treated as one unit takes a singular verb: *Ten thousand francs **is** a lot of money. Five kilometres **is** a long walk.* A title is singular even when it looks plural: *'Things Fall Apart' **is** a famous novel.* Subjects that end in *-s* but name a field of study are singular: *Mathematics **is** my favourite subject.* But *a pair of scissors **is**, scissors **are***."),
        T("**Each, every, either, neither, everyone** take singular verbs: *Neither of the answers **is** correct.* (Informal speech often uses *are* after *neither of*; stay with the singular for exams: check your textbook.) **None** may take a singular or a plural verb in some books: check your textbook."),
        T("**There is / There are.** The verb agrees with the noun that follows: *There **are** two reasons.* *There **is** a pen on the desk.* With a compound subject (*There is a pen and two books*), formal writing uses the plural when the subject is plural as a whole: check your textbook."),
        T("**One of the ... who.** In 'She is one of the students **who have** passed', *who* refers to *students* (plural), so the verb is plural. In 'She is the **only one** of the students **who has** passed', *who* refers to *one*, so the verb is singular."),
        H("Pronoun agreement"),
        T("A pronoun must agree with its **antecedent** (the noun it refers to) in number and person. *Each of the girls brought **her** own lunch.* *The company announced **its** profits.* *Every student must bring **his or her** card* (in current usage many people write *their*; check your textbook)."),
        EX("Worked example 1: find the true subject", intro="Choose: 'The list of required books (is / are) on the notice board.'", steps=[
            S("Find the verb and ask who or what", text="What is on the notice board? The **list**."),
            S("Ignore the phrase *of required books*", text="*List* is singular."),
            S("Answer", text="'The list of required books **is** on the notice board.'"),
        ]),
        EX("Worked example 2: neither ... nor", intro="Choose: 'Neither the coach nor the players (was / were) satisfied.'", steps=[
            S("Find the nearer subject", text="*Players* is nearer to the verb: plural."),
            S("Answer", text="'Neither the coach nor the players **were** satisfied.'"),
        ]),
        EX("Worked example 3: one of the ... who", intro="Choose: 'Ayuk is one of the pupils who (win / wins) prizes every year.'", steps=[
            S("Find what *who* stands for", text="*Who* stands for *pupils*, which is plural."),
            S("Answer", text="'Ayuk is one of the pupils who **win** prizes every year.'"),
        ]),
        MISTAKE("Agreeing with the nearest noun", "Wrong: *The cost of the repairs are high.* Right: *The cost of the repairs is high.* The subject is *cost*."),
        MISTAKE("Treating 'together with' like 'and'", "Wrong: *The principal, together with the teachers, are present.* Right: *...is present.* Use *and* for a plural subject: *The principal and the teachers are present.*"),
        QUIZ("'A number of farmers ______ attended the meeting.'", ["has", "have", "is", "was"], 1,
             "*A number of* = several, so a plural verb: *have*.", hint="Does *a number of* mean one number or several farmers?",
             feedback=["Singular.", "", "Singular.", "Singular."]),
        QUIZ("'The number of absent students ______ increased this week.'", ["have", "has", "are", "were"], 1,
             "*The number* is the subject: singular, so *has*.", hint="What is the subject: *number* or *students*?",
             feedback=["Plural.", "", "Plural.", "Plural."]),
        PQ("Correct the errors: (a) 'The principal, along with the prefects, are meeting parents.' (b) 'Either the manager or his assistants is available.'",
           "(a) 'The principal, along with the prefects, **is** meeting parents.' (b) 'Either the manager or his assistants **are** available.' (the nearer subject is plural)."),
        PQ("Explain why 'Five hundred francs is enough' is correct.",
           "The sum is thought of as one amount, so it takes a singular verb."),
        PQ("Choose the verb: 'She is the only one of my cousins who (speak / speaks) Bulu.'",
           "'**speaks**': *who* refers to *the only one* (singular)."),
        SUM("Find the true subject; ignore phrases between subject and verb.",
            "With, together with, as well as do not make a subject plural.",
            "Either/or and neither/nor: the verb agrees with the nearer subject.",
            "A number of = plural; the number of = singular.",
            "Pronouns agree with their antecedents; British collective nouns can take either number (check your textbook)."),
    ],
))

# ================================================================== 13. Fragments, run-ons, modifiers
LESSONS.append(lesson(
    module=M, topic=T_AGR,
    title="Fragments, run-on sentences and misplaced or dangling modifiers",
    slug="enl2-fragments-runons-modifiers",
    minutes=22,
    summary="A sentence needs a subject and a finite verb and must express a complete thought; two sentences must not be run together; and a modifier must sit next to the word it describes.",
    objectives=["Recognise sentence fragments and repair them", "Repair run-on sentences and comma splices in four ways", "Spot and correct misplaced modifiers, including only and almost",
                "Identify and repair dangling modifiers"],
    key_concepts=["Sentence fragment", "Run-on (fused) sentence", "Comma splice", "Misplaced modifier", "Dangling modifier"],
    blocks=[
        H("Introduction"),
        T("Three of the commonest faults in Cameroon's GCE essays are these: a sentence that is not finished, two sentences stuck together, and a descriptive phrase that attaches to the wrong word. Each is an exam item in Paper 1 Section C and a mark lost in Paper 2 accuracy and in Paper 3 editing."),
        H("Sentence fragments"),
        D("A **sentence fragment** is a group of words punctuated as a sentence that lacks a subject, a finite verb or a complete thought. Examples: *Because the rain stopped.* (dependent clause only), *Running down the road.* (participle phrase only), *The man who lived next door.* (a noun with a relative clause but no main verb).", title="Definition"),
        T("**Repair** by joining the fragment to a main clause, or by supplying the missing part: *Because the rain stopped, the match continued.* / *Running down the road, he dropped his bag.* / *The man who lived next door repairs bicycles.* Writers do use deliberate fragments for effect in stories (*Silence.*) and in dialogue; in exam essays and formal writing, write full sentences."),
        H("Run-on sentences and comma splices"),
        D("A **run-on (fused) sentence** joins two independent clauses with no punctuation: *The test was hard many students failed.* A **comma splice** joins them with only a comma: *The test was hard, many students failed.*", title="Definition"),
        KEY("Four repairs", "Choose the one that fits the meaning.", cards=[
            ["Full stop", "*The test was hard. Many students failed.*"],
            ["Semicolon", "*The test was hard; many students failed.*"],
            ["Comma + coordinating conjunction", "*The test was hard, and many students failed.*"],
            ["Subordinate one clause", "*Because the test was hard, many students failed.*"]]),
        T("A conjunctive adverb needs a semicolon: *...hard; consequently, many students failed.* A comma alone before *however, therefore, then* is a splice."),
        EX("Worked example 1: repair a run-on", intro="Repair: 'The generator broke down we studied by candlelight.'", steps=[
            S("Find the two clauses", text="*The generator broke down* / *we studied by candlelight*."),
            S("Choose a repair", text="'The generator broke down, so we studied by candlelight.' (cause and effect)"),
            S("Other correct repairs", text="'The generator broke down. We studied by candlelight.' or 'When the generator broke down, we studied by candlelight.'"),
        ]),
        H("Misplaced modifiers"),
        D("A **modifier** is a word or phrase that adds detail. A **misplaced modifier** is placed so that it seems to describe the wrong word. Put the modifier **next to what it modifies**.", title="Definition"),
        T("Limiting words such as *only, almost, nearly, even, just* go directly before the word they limit. Compare: *He almost drove for three hours* (he nearly started to drive) and *He drove for almost three hours* (a time just under three hours). *She only eats fish* (she does nothing else with fish) is common in speech; for the exam meaning 'she eats nothing but fish', write *She eats only fish*."),
        T("Phrases can be misplaced too: 'I saw a snake **walking to school**' (the snake walks to school?) becomes 'Walking to school, I saw a snake.' And 'The teacher told the students **on Friday** that there would be a test' is ambiguous: say *On Friday the teacher told the students that there would be a test* or *...that there would be a test on Friday*."),
        H("Dangling modifiers"),
        D("A **dangling modifier** is a phrase at the start of a sentence whose understood subject is not the subject of the main clause. 'Walking to school, **the rain** started' says that the rain was walking.", title="Definition"),
        T("Two repairs: **(1)** make the subject of the main clause the doer of the phrase: *Walking to school, Eka was caught in the rain.* **(2)** change the phrase into a full clause with its own subject: *While Eka was walking to school, the rain started.*"),
        EX("Worked example 2: dangling modifiers", intro="Repair: 'After finishing the report, the computer was switched off.'", steps=[
            S("Who finished the report?", text="A person, not the computer. The phrase dangles."),
            S("Repair 1: name the doer as subject", text="'After finishing the report, **the secretary** switched off the computer.'"),
            S("Repair 2: make a full clause", text="'After **she had finished** the report, the computer was switched off.'"),
        ]),
        T("A to-infinitive of purpose often dangles too: 'To pass the exam, hard work is needed.' Many modern books accept this, but a careful rewrite is safer: 'To pass the exam, students need to work hard.' Check your textbook."),
        MISTAKE("Fixing a comma splice by adding a comma", "A second comma does not fix a splice. You must change the punctuation or add a conjunction."),
        MISTAKE("Ignoring the understood subject", "Always ask of an opening phrase: 'Who or what is doing this?' The answer must be the subject of the main clause."),
        QUIZ("Which sentence is a comma splice?", ["The bus was late, so I walked.", "The bus was late, I walked.", "Because the bus was late, I walked.", "The bus was late; I walked."], 1,
             "Two independent clauses joined by only a comma.", hint="Look for two full clauses and no conjunction or semicolon.",
             feedback=["A coordinating conjunction is present.", "", "A subordinating conjunction is present.", "A semicolon is correct."]),
        QUIZ("Which sentence has a dangling modifier?", ["Driving home, I saw a goat.", "Driving home, a goat crossed the road.", "While I was driving home, a goat crossed the road.", "As I drove home, a goat crossed the road."], 1,
             "A goat was not driving: the phrase's subject is missing.", hint="Who is driving?",
             feedback=["The driver is the subject.", "", "Full clause with its own subject.", "Full clause with its own subject."]),
        PQ("Repair the fragment: 'Although the exam was difficult.' Make two correct sentences.",
           "'Although the exam was difficult, most candidates finished.' / 'The exam was difficult.' (Join to a main clause, or remove the subordinator.)"),
        PQ("Repair the comma splice in three ways: 'Rain fell all night, the river rose.'",
           "'Rain fell all night. The river rose.' / 'Rain fell all night; the river rose.' / 'Rain fell all night, so the river rose.' (or 'Because rain fell all night, the river rose.')"),
        PQ("Repair: 'Tired after the long journey, the bed looked inviting.'",
           "'Tired after the long journey, **we** thought the bed looked inviting.' or 'Because **we were** tired after the long journey, the bed looked inviting.' The bed was not tired."),
        SUM("A fragment lacks a subject, a finite verb or a complete thought; join it to a main clause.",
            "A run-on has no punctuation between clauses; a comma splice has only a comma.",
            "Repair with a full stop, a semicolon, a conjunction or a subordinate clause.",
            "Put modifiers next to the words they describe; only and almost go before the word they limit.",
            "An opening phrase must describe the subject of the main clause."),
    ],
))

# ================================================================== 14. Noun and adverb clauses
LESSONS.append(lesson(
    module=M, topic=T_CLAUSE,
    title="Noun clauses and adverb clauses",
    slug="enl2-noun-adverb-clauses",
    minutes=22,
    summary="A dependent clause does the job of a noun (what she said), or of an adverb (when, where, why, how, although, so that); each kind has its own linking words, word order and common errors.",
    objectives=["Recognise noun clauses as subject, object or complement and keep statement word order in them", "Name the adverb clauses of time, place, reason, condition, concession, purpose, result and manner",
                "Use although v despite correctly, and so...that / such...that", "Avoid double conjunctions such as 'although ... but'"],
    key_concepts=["Noun clause", "Adverb clause", "Subordinator", "Concession", "Purpose and result"],
    blocks=[
        H("Introduction"),
        T("In the last lesson on sentence types you met dependent clauses. A dependent clause always does a job inside the main clause, and the job tells us its name: it can be a **noun** clause, an **adjective** (relative) clause or an **adverb** clause. This lesson covers the first and last; relative clauses have their own lesson."),
        H("Noun clauses"),
        D("A **noun clause** is a dependent clause that does the job of a noun. It can be the subject, object or complement of a verb, or follow a preposition. It begins with *that, whether, if*, or a question word (*what, who, why, how, where, when*).", title="Definition"),
        CODE("Subject        What she said surprised everyone.\nObject         I know that the bus is late.\nObject         She asked where the clinic was.\nComplement     The problem is that we have no water.\nAfter prep.    We talked about how the project began.\nAfter noun     The fact that he lied disappointed us.", "text", title="Noun clauses at work"),
        T("**Word order in noun clauses is statement order**, even when the clause comes from a question: 'Where **is** the clinic?' but 'I do not know where the clinic **is**.' Never use *do/does/did* in the noun clause: 'She asked **where he lived**' (not *where did he live*)."),
        T("*That* can often be dropped after verbs such as *know, think, say, hope*: *I think (that) it will rain.* It cannot be dropped when the clause is the subject: *That he failed surprised us.*"),
        H("Adverb clauses"),
        D("An **adverb clause** is a dependent clause that does the job of an adverb: it tells when, where, why, how or under what condition the main action happens.", title="Definition"),
        CODE("KIND            CONJUNCTIONS                              EXAMPLE\nTime            when, while, after, before, until, as     We waited until the rain stopped.\nPlace           where, wherever                           Wherever he goes, he carries a notebook.\nReason          because, since, as                        She stayed because she was ill.\nCondition       if, unless, provided that                 Unless you hurry, you will miss the bus.\nConcession      although, though, even though, whereas    Although he was tired, he kept working.\nPurpose         so that, in order that                    He saved money so that he could buy a bicycle.\nResult          so ... that, such ... that                It was so cold that the lake froze.\nManner          as, as if, as though                      She talked as if she knew the answer.\nComparison      than, as ... as                           He is taller than his brother is.", "text", title="Eight kinds of adverb clause"),
        T("An adverb clause can come first or last. When it comes first, a comma follows it: *When the bell rang, the students left.* When it comes last, a comma is usually not needed: *The students left when the bell rang.*"),
        T("**Although v despite.** *Although, though, even though* introduce a clause (subject and verb). *Despite* and *in spite of* are followed by a noun phrase or gerund: *Although it rained, we played.* / *Despite the rain, we played.* / *Despite raining, ...* Never write *despite of*, and never use two linking words together: *Although it rained, but we played* is wrong."),
        T("**So ... that and such ... that.** *So* goes with an adjective or adverb: *The road was so bad that buses stopped.* *Such* goes with a noun phrase: *It was such a bad road that buses stopped.*"),
        T("**Purpose** is shown with *so that* + clause (often with *can/could/will/would*) or with an infinitive: *She studies hard so that she can win a scholarship.* / *She studies hard to win a scholarship.*"),
        EX("Worked example 1: noun clause word order", intro="Rewrite correctly: 'The inspector asked why did the shop close early.'", steps=[
            S("Find the noun clause", text="*why did the shop close early*: the object of *asked*."),
            S("Use statement order, no do-support", text="*why the shop closed early*"),
            S("Answer", text="'The inspector asked **why the shop closed early**.'"),
        ]),
        EX("Worked example 2: although or despite", intro="Complete: '______ the heavy rain, the match started on time.' Choose between Although / Despite.", steps=[
            S("What follows?", text="*The heavy rain* is a noun phrase, not a clause."),
            S("Choose", text="'**Despite** the heavy rain, the match started on time.' (*Although the rain was heavy* would be the clause form.)"),
        ]),
        EX("Worked example 3: result", intro="Combine: 'The soup was very hot. We could not eat it.' with so ... that.", steps=[
            S("Adjective follows so", text="*hot* is an adjective."),
            S("Answer", text="'The soup was **so hot that** we could not eat it.'"),
        ]),
        MISTAKE("Double linking words", "Wrong: *Although he was ill, but he came.* *Because it rained, so we stayed.* Right: *Although he was ill, he came.* *Because it rained, we stayed.* (Use one conjunction, not two.)"),
        MISTAKE("Question order in indirect questions", "Wrong: *Tell me where is the market.* *She asked what did I want.* Right: *Tell me where the market is.* *She asked what I wanted.*"),
        QUIZ("'He did not know ______ the key was.'", ["where", "where was", "where did", "that where"], 0,
             "A noun clause uses statement order: *where the key was*.", hint="Statement order or question order?",
             feedback=["", "This keeps the question order.", "This adds do-support.", "*That* is not used with a question word."]),
        QUIZ("'______ the long journey, they arrived fresh.'", ["Although", "Despite", "Even though", "Because"], 1,
             "*The long journey* is a noun phrase, so *despite*. The other three need a clause.", hint="Noun phrase or clause after the gap?",
             feedback=["Needs a clause.", "", "Needs a clause.", "Wrong meaning and needs a clause."]),
        PQ("Correct: 'Although the road was bad, but the bus arrived on time.'",
           "'**Although** the road was bad, the bus arrived on time.' (delete *but*) or 'The road was bad, but the bus arrived on time.'"),
        PQ("Name the kind of adverb clause: (a) 'Since he was ill, he stayed at home.' (b) 'She spoke as though she were the owner.' (c) 'We left early so that we could avoid the rain.'",
           "(a) **Reason** (b) **Manner** (c) **Purpose**."),
        PQ("Rewrite using so ... that: 'The test was very difficult. Nobody finished it.'",
           "'The test was **so difficult that** nobody finished it.'"),
        SUM("A noun clause does a noun's job; keep statement order in it.",
            "An adverb clause tells when, where, why, how or under what condition.",
            "Although/though + clause; despite/in spite of + noun or gerund.",
            "So + adjective/adverb + that; such + noun phrase + that.",
            "One conjunction per link: never although ... but."),
    ],
))

# ================================================================== 15. Relative clauses
LESSONS.append(lesson(
    module=M, topic=T_CLAUSE,
    title="Relative (adjective) clauses and prepositions",
    slug="enl2-relative-clauses",
    minutes=21,
    summary="A relative clause describes a noun; defining clauses identify it (no commas), non-defining clauses add extra information (commas, no 'that'); a preposition can come before whom/which or stay at the end.",
    objectives=["Choose who, whom, which, that, whose, where, when and why", "Tell defining from non-defining clauses and punctuate them", "Place prepositions in relative clauses (to whom / whom ... to)",
                "Use 'which' to comment on a whole clause and reduce relative clauses"],
    key_concepts=["Relative pronoun", "Defining clause", "Non-defining clause", "Preposition + whom/which", "Reduced relative clause"],
    blocks=[
        H("Introduction"),
        T("A **relative clause** (also called an adjective clause) describes a noun or pronoun and begins with a relative word. It is the commonest dependent clause in written English and a favourite in Paper 1 and Paper 3 sentence-combining tasks."),
        D("**Relative words:** *who, whom, whose* (people), *which* (things), *that* (people or things, defining only), *where* (place), *when* (time), *why* (reason). The clause comes directly after the noun it describes.", title="Definition"),
        CODE("The woman who teaches us is kind.            (subject)\nThe woman whom we met is a nurse.             (object; who is common in speech)\nThe boy whose bag was stolen cried.           (possession)\nThe bag that/which he lost was blue.          (object of lost)\nThe village where I was born is small.        (= in which)\nThe day when we arrived was Monday.           (= on which)\nThe reason why she left is unknown.           (= for which)", "text", title="Relative words at work"),
        H("Defining and non-defining"),
        KEY("Two kinds", "The commas change the meaning.", cards=[
            ["Defining (restrictive)", "Identifies which noun we mean, so it is essential. No commas; *that* is allowed: *Students who cheat are punished.* (only those who cheat)"],
            ["Non-defining (non-restrictive)", "Adds extra information about a noun already identified. Commas on both sides; *that* is NOT allowed: *My brother, who lives in Limbe, is a pilot.*"]]),
        T("Compare: 'The students **who failed** repeated the year' (only some students) and 'The students, **who failed**, repeated the year' (all of them failed). A proper name is already identified, so its clause is non-defining: *Mount Cameroon, which is an active volcano, attracts hikers.*"),
        H("Prepositions in relative clauses"),
        T("A preposition can stay at the end (informal and common) or move before *whom* or *which* (formal). 'The man **whom** I spoke **to**' = 'The man **to whom** I spoke.' 'The school **that** he studied **at**' = 'The school **at which** he studied.' After a preposition, use *whom/which*, never *that* or *who*: *the man to whom*, not *the man to that*. The relative pronoun may be left out when the preposition stays at the end: *the man I spoke to* is fine in speech."),
        T("**Which for a whole clause.** *Which* can refer to a whole idea: 'The bus broke down, **which** made us late.' Use a comma before it."),
        T("**Reduced relative clauses.** A relative pronoun plus *be* can be dropped: 'the girl (who is) standing at the gate', 'the books (which were) left on the bus'."),
        EX("Worked example 1: combine with a relative clause", intro="Combine: 'The nurse examined the baby. The nurse works at the clinic.' and 'My uncle lives in Garoua. My uncle is a pilot.'", steps=[
            S("First pair: identifies which nurse (defining)", text="'The nurse **who works at the clinic** examined the baby.'"),
            S("Second pair: extra information (non-defining)", text="'My uncle, **who is a pilot**, lives in Garoua.'"),
        ]),
        EX("Worked example 2: preposition", intro="Rewrite formally: 'This is the woman I told you about.'", steps=[
            S("Move the preposition before the relative pronoun", text="Add *whom*: 'This is the woman **about whom** I told you.'"),
        ]),
        EX("Worked example 3: punctuation and meaning", intro="Which version means that all the pupils were tired? (a) 'The pupils who were tired slept.' (b) 'The pupils, who were tired, slept.'", steps=[
            S("Apply the rule", text="Commas = extra information about all of them: **(b)**. (a) means only the tired ones."),
        ]),
        MISTAKE("That in a non-defining clause", "Wrong: *Mount Cameroon, that is a volcano, is high.* Right: *Mount Cameroon, which is a volcano, is high.*"),
        MISTAKE("Repeating the pronoun, or using what", "Wrong: *The book which I read it was long.* *The thing what he said.* Right: *The book which I read was long.* *What he said ...* or *The thing that he said...*"),
        QUIZ("'My cousin, ______ lives in Kribi, is a fisherman.'", ["that", "who", "whom", "which"], 1,
             "A non-defining clause about a person who is the subject: *who*. *That* is not used in non-defining clauses.", hint="Commas present; person; subject.",
             feedback=["*That* cannot be used with commas.", "", "*Whom* is for objects.", "*Which* is for things."]),
        QUIZ("'The teacher to ______ I gave the letter was absent.'", ["who", "that", "whom", "which"], 2,
             "After a preposition about a person, use *whom*.", hint="Preposition + person.",
             feedback=["Not used after a preposition in formal English.", "Not used directly after a preposition.", "", "*Which* is for things."]),
        PQ("Join, adding commas where needed: 'Lake Barombi Mbo is in the South-West Region. Lake Barombi Mbo is a crater lake.'",
           "'Lake Barombi Mbo, **which is a crater lake**, is in the South-West Region.' (non-defining: a proper name)"),
        PQ("Rewrite without a preposition at the end: 'That is the village I come from.'",
           "'That is the village **from which** I come.'"),
        PQ("Explain the difference: 'My sisters who live in Douala are nurses' and 'My sisters, who live in Douala, are nurses.'",
           "The first implies I have other sisters living elsewhere (defining). The second says all my sisters live in Douala (extra information)."),
        SUM("Who/whom/whose for people, which for things, that for either (defining only).",
            "Defining: no commas, that allowed. Non-defining: commas, no that.",
            "After a preposition use whom/which.",
            "Which can comment on a whole clause.",
            "Do not repeat the pronoun inside the clause."),
    ],
))

# ================================================================== 16. Comparatives, superlatives, conjunctions
LESSONS.append(lesson(
    module=M, topic=T_COMP,
    title="Comparatives, superlatives and conjunctions",
    slug="enl2-comparison-conjunctions",
    minutes=21,
    summary="Adjectives and adverbs have comparative and superlative forms (-er/-est or more/most) and special irregular forms; pairs such as both...and, either...or, not only...but also must be balanced; conjunctions must be chosen for their meaning.",
    objectives=["Form comparatives and superlatives, including irregular forms and the double-comparison error", "Use as...as, the + comparative...the + comparative, and than correctly",
                "Choose conjunctions by meaning: contrast, reason, result, addition", "Keep correlative conjunctions parallel"],
    key_concepts=["Comparative", "Superlative", "Irregular comparison", "Correlative conjunction", "Parallel structure"],
    blocks=[
        H("Introduction"),
        T("Comparison and linking are everywhere in exam English: *better than, the most important, neither ... nor, not only ... but also*. The rules are small but strict."),
        H("Forming comparatives and superlatives"),
        CODE("SHORT (1 syllable)     tall  taller  tallest      big  bigger  biggest\n-y words              happy happier happiest     (y becomes i)\nLONG (3+ syllables)   beautiful  more beautiful  most beautiful\n2 syllables           clever: cleverer/more clever; follow the dictionary\nIRREGULAR             good  better  best     bad  worse  worst\n                      far  farther/further  farthest/furthest\n                      little  less  least    many/much  more  most", "text", title="Patterns"),
        T("**Never double a comparison.** Wrong: *more better, most easiest, more taller.* Right: *better, easiest, taller.* **Use the comparative for two, the superlative for three or more**: *the taller of the two girls* (many books accept *tallest* in speech); *the tallest of the three girls*. Adverbs follow the same pattern: *fast, faster, fastest; carefully, more carefully, most carefully.*"),
        T("**Comparing correctly.** Use *than* after a comparative: *Douala is bigger than Limbe.* Compare like with like: wrong *The climate of Buea is cooler than Douala* (climate with a town); right *...cooler than that of Douala* or *...than Douala's.* Exclude the thing from the group: *Mount Cameroon is higher than any other mountain in Cameroon* (not *any mountain*)."),
        T("**As ... as** shows equality: *She is as tall as her sister.* The negative may be *not as/so tall as*. **The ... the** pairs: *The harder you work, the better you perform.* **Fewer/less**: see the lesson on nouns (check your textbook)."),
        KEY("Comparative forms in the exam", "Check these every time.", cards=[
            ["Double comparison", "*more faster* is an error."],
            ["Unfinished comparison", "*This phone is cheaper* needs a second term only when the comparison is meant: *cheaper than that one*."],
            ["Superlative", "Takes *the*: *the best result*, *the most useful book*."]]),
        H("Conjunctions"),
        T("Choose by meaning. **Addition:** *and, as well as, moreover.* **Contrast:** *but, yet, although, whereas, however.* **Reason:** *because, since, as, for.* **Result:** *so, therefore, consequently, so ... that.* **Alternative:** *or, otherwise, either ... or.* **Condition:** *if, unless, provided that.* **Time:** *when, while, before, after, until.*"),
        T("**Correlative conjunctions** come in pairs: *both ... and, either ... or, neither ... nor, not only ... but also, whether ... or.* The words after each half must have the same grammatical form (**parallel structure**). Wrong: *She is both a nurse and studies at night.* Right: *She is both a nurse and a student.* Or: *She both works as a nurse and studies at night.* With *neither/nor* use no other negative: *He neither called nor wrote* (not *did not neither*)."),
        T("When *not only* begins a sentence, the auxiliary comes before the subject: *Not only did she pass, but she also won a prize.*"),
        EX("Worked example 1: comparison errors", intro="Correct: 'Her results are more better than her brother.'", steps=[
            S("Remove the double comparative", text="*Better* already is a comparative."),
            S("Compare like with like", text="Results with results: *than her brother's*."),
            S("Answer", text="'Her results are **better than her brother's**.'"),
        ]),
        EX("Worked example 2: parallel structure", intro="Correct: 'The new teacher is not only strict but also has a sense of humour.'", steps=[
            S("Look after each half", text="*strict* (adjective) but *has a sense of humour* (verb phrase): not parallel."),
            S("Make both halves adjectives or both verb phrases", text="'The new teacher is not only strict but also humorous.' or 'The new teacher not only is strict but also has a sense of humour.'"),
        ]),
        EX("Worked example 3: choosing the conjunction", intro="Choose: 'The road was repaired; (however / therefore), buses now arrive on time.'", steps=[
            S("Is the second idea a result or a contrast?", text="Repair leads to punctual buses: a result."),
            S("Answer", text="**therefore**"),
        ]),
        MISTAKE("Most of two", "Use the comparative for two: *Which is better, tea or coffee?* not *best*. For three or more, use the superlative."),
        MISTAKE("Broken pairs", "*Neither ... or* and *either ... nor* are errors. Pair *either ... or* and *neither ... nor*."),
        QUIZ("'Of the two roads, this one is ______.'", ["safest", "the safer", "more safer", "most safe"], 1,
             "Two items: the comparative, with *the* when it means 'the safer of the two'.", hint="How many roads?",
             feedback=["Superlative is for three or more.", "", "Double comparison.", "Wrong superlative form for this word and number."]),
        QUIZ("Which sentence is correct?", ["She is neither tall or short.", "She is neither tall nor short.", "She is not neither tall nor short.", "She neither is tall or short."], 1,
             "*Neither* pairs with *nor*.", hint="Which word completes neither?",
             feedback=["*Or* does not pair with neither.", "", "A double negative.", "Wrong pair and awkward order."]),
        PQ("Correct: 'Joy is the most cleverest girl in the class.'",
           "'Joy is the **cleverest** girl in the class.' (no *most*; or 'the most clever' alone)."),
        PQ("Join with a correlative pair: 'Ako plays football. Ako plays volleyball.'",
           "'Ako plays **both** football **and** volleyball.' or 'Ako plays **not only** football **but also** volleyball.'"),
        PQ("Correct the comparison: 'The population of Yaounde is larger than Bamenda.'",
           "'The population of Yaounde is larger than **that of** Bamenda.' (compare population with population)"),
        SUM("Short words add -er/-est; long words use more/most; learn better/best, worse/worst.",
            "Never double a comparison; use the comparative for two and the superlative for three or more.",
            "Compare like with like and add 'other' when the item belongs to the group.",
            "Pairs: both...and, either...or, neither...nor, not only...but also; keep them parallel.",
            "Choose conjunctions by meaning: contrast, reason, result, addition."),
    ],
))

# ================================================================== 17. Word order
LESSONS.append(lesson(
    module=M, topic=T_COMP,
    title="Word order: questions, tags, requests, adjectives, adverbs and enough",
    slug="enl2-word-order",
    minutes=22,
    summary="English meaning depends on order: questions put the auxiliary before the subject, adjectives follow a fixed sequence, adverbs sit in set places, enough follows an adjective but precedes a noun, and question tags mirror the main verb.",
    objectives=["Form direct questions, subject questions and polite indirect questions", "Build correct question tags, including tags after imperatives and I am", "Order several adjectives before a noun",
                "Place frequency adverbs, manner adverbs and enough correctly"],
    key_concepts=["Inversion", "Question tag", "Adjective order", "Adverb position", "Enough"],
    blocks=[
        H("Introduction"),
        T("English has little verb change, so word order carries the meaning. 'The dog bit the man' and 'The man bit the dog' differ only in order. The Board's syllabus names the cases to know: questions, question tags, requests, adjectives and nouns, main verb and auxiliary, enough, participles with adverbs, and relative pronouns with prepositions."),
        H("Questions"),
        T("**Yes/no questions** put the auxiliary (or modal, or *be*) before the subject: *Are you ready? Can she swim? Have they arrived?* With no auxiliary in the statement, add *do/does/did*: *Does he live here?* **Wh-questions** put the question word first, then the same order: *Where did she go? How long have you waited?*"),
        T("**Exception: subject questions.** When the question word is the subject, there is no inversion and no *do*: *Who called you?* (not *Who did call you*). *What happened?* *Which student won?*"),
        T("**Indirect questions** (polite requests for information) return to statement order: *Could you tell me where the bank is?* (not *where is the bank*). *Do you know what time it starts?*"),
        H("Question tags"),
        D("A **question tag** is a short question added to a statement to ask for agreement. It repeats the auxiliary of the statement and a pronoun for the subject. A positive statement takes a negative tag and a negative statement takes a positive tag.", title="Definition"),
        CODE("You are coming, aren't you?          She can swim, can't she?\nThey didn't call, did they?          He has gone, hasn't he?\nShe likes tea, doesn't she?          (no auxiliary: use do/does/did)\nI am late, aren't I?                 (special: aren't I)\nOpen the door, will you?             Let's go, shall we?\nNobody called, did they?             There is a seat, isn't there?", "text", title="Question tags"),
        T("After *nobody, no one, nothing, never, hardly* the statement is negative in meaning, so the tag is positive. After *everyone, someone* use *they*."),
        H("Adjectives and nouns"),
        T("Several adjectives follow a usual order: **number, opinion, size, age, shape, colour, origin, material, purpose, then the noun.** 'a lovely old round wooden table', 'three small red plastic buckets', 'two big black Cameroonian goats'. The exam sometimes accepts small variations: check your textbook. Adjectives come after the noun only in fixed phrases and after linking verbs: *the president elect, attorney general, The soup tastes good.*"),
        H("Adverbs, auxiliaries and enough"),
        T("**Frequency adverbs** (*always, never, often, usually, seldom, just, already*) go **before the main verb** but **after the verb *be* and after the first auxiliary**: *She always arrives early. She is always early. She has never been late.*"),
        T("**Manner adverbs** usually follow the verb and its object, not come between them: *She speaks English well* (not *speaks well English*). Order for several: manner, place, time: *He worked hard in the garden yesterday.*"),
        T("**Enough** follows an adjective or adverb but precedes a noun: *She is tall enough. He runs fast enough. We have enough water.* (*Enough tall* is an error.) **Too** goes before an adjective: *too tired to walk.*"),
        T("**Participles with adverbs** put the adverb before the participle: *a carefully written essay, a well-known author, a badly damaged road.*"),
        T("**Relative pronoun and preposition:** see the lesson on relative clauses: *the man to whom I spoke*, or *the man I spoke to*."),
        EX("Worked example 1: tags", intro="Add the tag: (a) 'She has finished her homework, ___?' (b) 'They didn't attend the meeting, ___?' (c) 'Let's start now, ___?'", steps=[
            S("(a) positive statement, auxiliary has", text="**hasn't she**"),
            S("(b) negative statement, auxiliary did", text="**did they**"),
            S("(c) suggestion with let's", text="**shall we**"),
        ]),
        EX("Worked example 2: adjective order", intro="Arrange: 'wooden / a / table / old / beautiful'.", steps=[
            S("Opinion, age, material, noun", text="beautiful (opinion) → old (age) → wooden (material)."),
            S("Answer", text="'a **beautiful old wooden table**'"),
        ]),
        EX("Worked example 3: indirect question", intro="Make polite: 'Where is the post office?' beginning 'Could you tell me ...'", steps=[
            S("Use statement order", text="'Could you tell me **where the post office is**?'"),
        ]),
        MISTAKE("Inversion in indirect questions", "Wrong: *Do you know where is the hospital?* Right: *Do you know where the hospital is?*"),
        MISTAKE("Wrong adverb or enough position", "Wrong: *She arrives always late*, *enough tall*, *He speaks fluently English.* Right: *She always arrives late*, *tall enough*, *He speaks English fluently.*"),
        QUIZ("'Your brother plays football, ______?'", ["isn't he", "doesn't he", "didn't he", "does he"], 1,
             "Positive present-simple statement, no auxiliary: *doesn't he*.", hint="Which auxiliary does *plays* hide?",
             feedback=["The auxiliary would be *is*, not present here.", "", "Past tense tag.", "A positive statement needs a negative tag."]),
        QUIZ("Which is the correct order?", ["a red small plastic bucket", "a small red plastic bucket", "a plastic small red bucket", "a small plastic red bucket"], 1,
             "Size, colour, material, noun.", hint="Size before colour before material.",
             feedback=["Colour before size is wrong.", "", "Material comes last.", "Material comes after colour."]),
        PQ("Correct: 'Do you know where is the headmaster's office?' and 'He is enough old to vote.'",
           "'Do you know where the headmaster's office **is**?' and 'He is **old enough** to vote.'"),
        PQ("Add the tag: 'Nobody told you, ___?' and 'I am right, ___?'",
           "'Nobody told you, **did they**?' and 'I am right, **aren't I**?'"),
        PQ("Rewrite with the adverb in the correct place: 'She goes to church on Sundays always.'",
           "'She **always goes** to church on Sundays.'"),
        SUM("Questions: auxiliary before subject; subject questions and indirect questions keep statement order.",
            "Tags: reverse the polarity and repeat the auxiliary; aren't I; shall we; will you.",
            "Adjectives: number, opinion, size, age, shape, colour, origin, material, noun.",
            "Frequency adverbs before the main verb, after be; enough after adjectives, before nouns.",
            "Adverb before a participle: carefully written."),
    ],
))

# ================================================================== 18. Word forms
LESSONS.append(lesson(
    module=M, topic=T_FORMS,
    title="Word forms: choosing the right form for the position",
    slug="enl2-word-forms",
    minutes=21,
    summary="A word has noun, verb, adjective and adverb forms; the position in the sentence tells you which form is needed, and suffixes, irregular plurals and pairs such as good/well and hard/hardly help you choose.",
    objectives=["Use the position of a gap to decide the part of speech needed", "Form nouns, adjectives, verbs and adverbs from a base word using common suffixes", "Choose between pairs such as good/well, hard/hardly, late/lately",
                "Use irregular plural and verb forms correctly"],
    key_concepts=["Word family", "Suffix", "Irregular plural", "Adjective v adverb", "Position clue"],
    blocks=[
        H("Introduction"),
        T("Paper 3 Text reconstruction and Paper 1 grammar items often give you a word in brackets and ask you to put it into the right form: 'Her ______ (decide) to resign surprised everyone.' You must work out which part of speech the gap needs. The method is the same every time: **read the words around the gap, name the part of speech needed, then build that form.**"),
        H("Position tells you the part of speech"),
        CODE("After a/an/the/my/this, before a noun      ADJECTIVE      a successful business\nAfter a/an/the/my (no noun follows)            NOUN           Her decision surprised us.\nAfter is/was/seems/becomes                     ADJECTIVE      She is successful.\nBefore/after a verb, modifying it              ADVERB         She spoke confidently.\nBefore an adjective, modifying it              ADVERB         very successfully tested\nAfter a modal (can, must, will)                BASE VERB      She must decide.\nAfter have/has/had                             PAST PARTICIPLE  She has decided.\nAfter a preposition                            NOUN or -ING   by deciding / by decision", "text", title="Reading the gap"),
        H("Word families and suffixes"),
        CODE("VERB         NOUN              ADJECTIVE        ADVERB\ndecide       decision          decisive         decisively\nsucceed      success           successful       successfully\ndiffer       difference        different        differently\nchoose       choice            choosy           -\nbeauty (n)   beautify (v)      beautiful        beautifully\nstrong (adj) strength; strengthen (v)  -        strongly\nact          action; actor     active           actively\nsafe (adj)   safety            safe             safely", "text", title="Word families"),
        T("Suffix clues: **nouns** often end in *-tion, -sion, -ment, -ness, -ity, -ence/-ance, -ship*; **adjectives** in *-ous, -ful, -ive, -al, -able, -ic, -less*; **adverbs** in *-ly*; **verbs** in *-ise/-ize, -ify, -en* (*modernise, simplify, shorten*). Spelling changes when a suffix is added: *happy → happiness, happily; decide → decision; true → truly; argue → argument.*"),
        H("Pairs that cause errors"),
        KEY("Adjective or adverb?", "Same root, different jobs and sometimes different meanings.", cards=[
            ["good / well", "*Good* is an adjective: *a good singer.* *Well* is the adverb: *She sings well.* (*Well* is also an adjective meaning healthy: *I feel well.*)"],
            ["hard / hardly", "*Hard* = with effort: *He worked hard.* *Hardly* = almost not: *He hardly worked.*"],
            ["late / lately", "*Late* = after the expected time: *She came late.* *Lately* = recently."],
            ["near / nearly", "*Near* = close: *near the market.* *Nearly* = almost: *nearly finished.*"],
            ["high / highly", "*High* = to a great height: *flew high.* *Highly* = very: *highly intelligent.*"],
            ["economic / economical", "*Economic* relates to the economy: *economic growth.* *Economical* = saving money: *an economical car.*"]]),
        H("Irregular forms"),
        T("**Irregular plurals:** *child → children, man → men, woman → women, tooth → teeth, foot → feet, person → people (or persons in formal legal use), crisis → crises, analysis → analyses, thesis → theses, criterion → criteria, phenomenon → phenomena.* Words such as *datum/data* and *medium/media* are used differently in different books (*data* as singular or plural; *media* as singular or plural): check your textbook."),
        T("**Irregular verbs** have their own past and past participle: *begin, began, begun; choose, chose, chosen; write, wrote, written; teach, taught, taught; lie (recline), lay, lain; lay (put), laid, laid.* After *have/has/had* or in the passive, use the past participle: *She has written* (not *has wrote*)."),
        EX("Worked example 1: fill with the correct form", intro="Complete with the word in brackets: 'The (decide) of the committee was announced (public) yesterday, and it was (surprise) to many.'", steps=[
            S("First gap: after *The*, before *of*", text="A noun is needed: **decision**."),
            S("Second gap: modifies the verb *was announced*", text="An adverb: **publicly** (note the spelling: public + ly = *publicly*, not *publically*)."),
            S("Third gap: after *was*, followed by *to many*", text="An adjective: **surprising** (the news surprises people)."),
        ]),
        EX("Worked example 2: adjective or adverb", intro="Choose: (a) 'She did (good / well) in the test.' (b) 'He could (hard / hardly) speak.'", steps=[
            S("(a) The word describes how she did", text="Adverb: **well**."),
            S("(b) Meaning: almost unable", text="**hardly**"),
        ]),
        EX("Worked example 3: irregular forms", intro="Correct: 'The scientists studied two phenomenon, and the analysises were published.'", steps=[
            S("Irregular plurals", text="*phenomenon → phenomena*; *analysis → analyses*."),
            S("Answer", text="'The scientists studied two **phenomena**, and the **analyses** were published.'"),
        ]),
        MISTAKE("Using an adjective to modify a verb", "Wrong: *She sings beautiful. He drives careful.* Right: *She sings beautifully. He drives carefully.* (Linking verbs take adjectives: *She looks beautiful.*)"),
        MISTAKE("Wrong participle after have", "Wrong: *has wrote, have went, had spoke, was broke.* Right: *has written, have gone, had spoken, was broken.*"),
        QUIZ("'She is a very ______ (success) businesswoman.'", ["success", "successful", "successfully", "succeeded"], 1,
             "A gap between *very* and a noun needs an adjective: *successful*.", hint="What follows the gap?",
             feedback=["A noun, not an adjective.", "", "An adverb modifies verbs or adjectives, not a noun.", "A verb form."]),
        QUIZ("'The students worked (hard) so they did ______ in the exam.'", ["good", "well", "hardly", "hard"], 1,
             "*Did well* describes how they did: the adverb *well*.", hint="Adjective or adverb after *did*?",
             feedback=["*Good* is an adjective.", "", "Means almost not.", "Does not fit the meaning."]),
        PQ("Complete: 'The (organise) of the festival was (excellent), and everyone left (happy).' Use the correct forms.",
           "'The **organisation** of the festival was **excellent**, and everyone left **happy**.' (*Left happy* describes the people: an adjective; *happily* would describe how they left, a different meaning.)"),
        PQ("Explain the difference between 'She hardly passed' and 'She passed with a hard effort'.",
           "*Hardly* means almost not, so she barely passed. In the second, *hard* is an adjective meaning difficult or intense."),
        PQ("Give the plural of each: criterion, crisis, child, thesis.",
           "criteria, crises, children, theses."),
        SUM("The position of the gap tells you the part of speech needed.",
            "Suffixes help: -tion, -ment, -ness (nouns); -ful, -ous, -ive (adjectives); -ly (adverbs); -ise, -ify, -en (verbs).",
            "Learn pairs: good/well, hard/hardly, late/lately, near/nearly, high/highly.",
            "Learn irregular plurals and past participles.",
            "Check spelling changes when adding a suffix (publicly, happiness, truly)."),
    ],
))

# ================================================================== 19. Punctuation
LESSONS.append(lesson(
    module=M, topic=T_PUNCT,
    title="Punctuation: commas, semicolons, colons, apostrophes, quotation marks and hyphens",
    slug="enl2-punctuation",
    minutes=22,
    summary="Punctuation marks show how clauses and words relate: commas separate items and extras, semicolons and colons link clauses, apostrophes show possession and omission, and quotation marks, dashes and hyphens each have set uses.",
    objectives=["Place commas in lists, after introductory clauses and around extra information", "Use semicolons and colons correctly", "Place apostrophes in singular and plural possessives and contractions (its v it's)",
                "Punctuate direct speech and use hyphens in compound modifiers"],
    key_concepts=["Comma", "Semicolon", "Colon", "Apostrophe", "Quotation marks", "Hyphen and dash"],
    blocks=[
        H("Introduction"),
        T("Punctuation is part of grammar: 'Let's eat, Grandma' and 'Let's eat Grandma' mean very different things. Paper 1 Section C and Paper 3 Editing test the rules below. Capital letters and the basic full stop were covered at O Level."),
        H("The comma"),
        KEY("Six uses of the comma", "Learn the reason, not just the mark.", cards=[
            ["Items in a list", "*We bought rice, beans, oil and salt.* A comma before the last *and* (the Oxford or serial comma) is optional in British English and usual in American; use it if it prevents confusion: check your textbook."],
            ["After an introductory clause or phrase", "*When the bell rang, the pupils left.* *In the morning, we went to market.*"],
            ["Before and, but, or, so joining two full clauses", "*It rained, but the match continued.*"],
            ["Around extra information", "*My cousin, who lives in Kumba, is a teacher.* (non-defining)"],
            ["Direct address and interrupters", "*Ngu, come here. The plan, however, failed.*"],
            ["Between coordinate adjectives", "*a long, difficult journey* (but *a small red bag*, no comma)."]]),
        T("**Do not** put a comma between the subject and its verb (*The students of this school, are clever* is wrong) and **do not** splice two clauses with a comma alone."),
        H("Semicolon and colon"),
        T("A **semicolon** joins two closely related independent clauses (*The road was flooded; we stayed home.*), and separates items in a list when the items already contain commas (*We visited Bamenda, in the North-West; Buea, in the South-West; and Maroua, in the Far North.*). A **colon** introduces a list, an explanation or a quotation after a complete clause: *She bought three things: rice, oil and salt.* Do not put a colon right after a verb or preposition: *We need: rice and oil* is wrong."),
        H("The apostrophe"),
        CODE("Singular possessive            the girl's bag              (one girl)\nPlural possessive in -s         the girls' bags             (more than one girl)\nIrregular plural possessive     the children's books, the women's club\nContractions                    don't, it's (it is), they're, who's (who is)\nSpecial                         its (belonging to it), whose, their, theirs, yours: no apostrophe\nPlurals                         tomatoes, CDs, the 1990s: no apostrophe for plurals", "text", title="Apostrophe rules"),
        T("Test: expand it to the long form. If *it is* or *it has* fits, write *it's*; if not, write *its*. Names ending in -s: *James's book* or *James' book* are both seen: check your textbook."),
        H("Quotation marks and direct speech"),
        T("British style uses single quotation marks and double ones inside a quotation; American style does the opposite. Start a new line for a new speaker. In direct speech, the spoken words begin with a capital letter and are set off with a comma (or a question or exclamation mark) inside the closing mark in most exam books: 'Where are you going?' she asked. / She said, 'I am going to the market.' Reported speech takes no quotation marks and no question mark for an indirect question. Placement of full stops and commas relative to the closing mark differs between British and American practice: check your textbook."),
        H("Hyphens and dashes"),
        T("A **hyphen** joins words into one idea: *a well-known writer, a ten-year-old girl, mother-in-law, re-sign (sign again) v resign*. Do not hyphenate when the modifier follows the noun: *The writer is well known.* An adverb ending in *-ly* is not hyphenated: *a carefully written essay*. A **dash** (longer than a hyphen) marks a break or an added thought: *She had one wish — to pass.* Brackets enclose extra information: *The conference (held in Bafoussam) lasted three days.*"),
        T("Use a **question mark** only for direct questions; use an **exclamation mark** sparingly (one, not several). An **ellipsis** (three dots) shows words left out or a pause."),
        EX("Worked example 1: commas", intro="Punctuate: 'When we reached Douala the market was closed so we went to a hotel.'", steps=[
            S("Introductory clause", text="Comma after *Douala*."),
            S("Two full clauses joined by *so*", text="Comma before *so*."),
            S("Answer", text="'When we reached Douala, the market was closed, so we went to a hotel.'"),
        ]),
        EX("Worked example 2: apostrophes", intro="Correct: 'The childrens toys were left in the girls room, and the dog wagged its tail.'", steps=[
            S("Irregular plural possessive", text="*children's*."),
            S("One room belonging to the girls (several girls)", text="*girls'*. (If one girl, *girl's*.)"),
            S("Its", text="*its tail* is correct: possession, no apostrophe."),
            S("Answer", text="'The **children's** toys were left in the **girls'** room, and the dog wagged its tail.'"),
        ]),
        EX("Worked example 3: direct speech", intro="Punctuate: 'Are you coming to the match asked Efe'", steps=[
            S("The spoken words are a question", text="Question mark inside the quotation marks."),
            S("Answer", text="'Are you coming to the match?' asked Efe."),
        ]),
        MISTAKE("It's and its", "*It's* always means *it is* or *it has*. Wrong: *The school lost it's roof.* Right: *The school lost its roof.*"),
        MISTAKE("Apostrophe in plurals", "Wrong: *Tomato's for sale, the 1990's, two CD's.* Right: *tomatoes for sale, the 1990s, two CDs.*"),
        QUIZ("Which sentence is correctly punctuated?", ["The students books were on the desk.", "The student's books were on the desk.", "The students' books were on the desk.", "The students books' were on the desk."], 2,
             "Several students own the books: plural possessive *students'*.", hint="Whose books: one student or many?",
             feedback=["Missing the apostrophe.", "That would mean one student's books.", "", "The apostrophe is after the wrong word."]),
        QUIZ("Which sentence uses a semicolon correctly?", ["I wanted to go; because I was tired.", "I was tired; I stayed home.", "I was; tired, and I stayed home.", "Although I was tired; I stayed home."], 1,
             "Two independent clauses of related meaning.", hint="What must be on each side of a semicolon?",
             feedback=["A dependent clause follows the semicolon.", "", "Splits a single clause.", "A dependent clause precedes the semicolon."]),
        PQ("Punctuate: 'my aunt who lives in kumba sells fish yams and plantains'",
           "'My aunt, who lives in Kumba, sells fish, yams and plantains.' (capital letters, commas for the extra information and the list)"),
        PQ("Choose its or it's: (a) '___ raining again.' (b) 'The company changed ___ name.'",
           "(a) **It's** (it is). (b) **its** (belonging to it)."),
        PQ("Write correctly: the hats of the women, the hat of the woman, and the toys of the children.",
           "the **women's** hats, the **woman's** hat, the **children's** toys."),
        SUM("Commas: lists, after introductory clauses, before a conjunction joining two clauses, around extras.",
            "Semicolon joins related independent clauses; colon introduces a list or explanation after a complete clause.",
            "Apostrophe: girl's, girls', children's; its (possessive) has none; it's = it is.",
            "Quotation marks: single in British style, double in American; check your textbook.",
            "Hyphens join compound modifiers before a noun; no hyphen after -ly adverbs."),
    ],
))
